INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (123,15,NULL,NULL,NULL,'\"<div class=\\\"fl-module fl-module-rich-text fl-node-5ba9c9b8cd0a4\\\" data-node=\\\"5ba9c9b8cd0a4\\\" data-animation-delay=\\\"0.0\\\" style=\\\"box-sizing: border-box; zoom: 1; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><div class=\\\"fl-module-content fl-node-content\\\" style=\\\"box-sizing: border-box; zoom: 1; margin: 0px;\\\"><div class=\\\"fl-rich-text\\\" style=\\\"box-sizing: border-box;\\\"><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần báo giá vận chuyển hàng hóa từ Sài Gòn Đi Phú Quốc hay báo giá về một dịch vụ nào đó?</em><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><span>&nbsp;</span>hãy gọi<span>&nbsp;</span><a href=\\\"tel:0945000006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0945000006</a></strong></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần điều xe vận chuyển để lấy hàng sau khi đã thỏa thuận xong về giá cả?</em><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">hãy gọi<span>&nbsp;</span><a href=\\\"tel:0917400006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0917400006</a></strong></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần hỏi đường đi đến Chành xe HCM để gửi hàng đi Phú Quốc?</em><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">hãy gọi<span>&nbsp;</span><a href=\\\"tel:0947700006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0947700006</a></strong></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần hỏi thông tin của một lô hàng nhỏ lẻ, đang ở đâu, khi nào giao hàng?</em><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">hãy gọi<span>&nbsp;</span><a href=\\\"tel:0942300006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0942300006</a></strong></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần xuất hóa đơn vận chuyển hoặc đối chiếu công nợ?</em><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">hãy gọi<span>&nbsp;</span><a href=\\\"tel:0942700006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0942700006</a></strong></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><em style=\\\"box-sizing: border-box;\\\">Cần hỏi đường đi đến Chành xe tại Phú Quốc để nhận hàng nhỏ lẻ tại Phú Quốc?</em><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><span>&nbsp;</span>hãy gọi<span>&nbsp;</span><a href=\\\"tel:0947700006\\\" rel=\\\"nofollow\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">0947700006</a></strong></p></div></div></div><div class=\\\"fl-module fl-module-rich-text fl-node-60b9f39229912\\\" data-node=\\\"60b9f39229912\\\" data-animation-delay=\\\"0.0\\\" style=\\\"box-sizing: border-box; zoom: 1; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><div class=\\\"fl-module-content fl-node-content\\\" style=\\\"box-sizing: border-box; zoom: 1; margin: 0px;\\\"><div class=\\\"fl-rich-text\\\" style=\\\"box-sizing: border-box;\\\"><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><img decoding=\\\"async\\\" class=\\\"alignnone size-full wp-image-5362\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/04/THONG-TIN-CRB-2023-05-scaled.jpg\\\" alt=\\\"THONG TIN CRB 2023 05 scaled\\\" width=\\\"1810\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/04/THONG-TIN-CRB-2023-05-scaled.jpg 1810w, https://conruabien.vn/wp-content/uploads/2023/04/THONG-TIN-CRB-2023-05-768x1086.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/04/THONG-TIN-CRB-2023-05-1086x1536.jpg 1086w, https://conruabien.vn/wp-content/uploads/2023/04/THONG-TIN-CRB-2023-05-1448x2048.jpg 1448w\\\" sizes=\\\"(max-width: 1810px) 100vw, 1810px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px; vertical-align: middle; margin: 5px 20px 20px 0px;\\\"></p></div></div></div>\"',NULL,'/lien-he',NULL,0,6,NULL,NULL,NULL);
INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (124,1,NULL,NULL,NULL,'\"<div class=\\\"fl-col fl-node-5ba99e26448c6 fl-col-small\\\" data-node=\\\"5ba99e26448c6\\\" style=\\\"box-sizing: border-box; zoom: 1; float: left; min-height: 1px; width: 530px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><div class=\\\"fl-col-content fl-node-content\\\" style=\\\"box-sizing: border-box;\\\"><div class=\\\"fl-module fl-module-rich-text fl-node-5ba99e2a6cb06\\\" data-node=\\\"5ba99e2a6cb06\\\" data-animation-delay=\\\"0.0\\\" style=\\\"box-sizing: border-box; zoom: 1;\\\"><div class=\\\"fl-module-content fl-node-content\\\" style=\\\"box-sizing: border-box; zoom: 1; margin: 20px;\\\"><div class=\\\"fl-rich-text\\\" style=\\\"box-sizing: border-box;\\\"><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold; font-size: 14px;\\\">Công ty TNHH Dịch vụ Hàng hóa Con Rùa Biển là đơn vị cung cấp dịch vụ vận chuyển hàng hóa chuyên nghiệp, uy tín hiện nay. Với nhiều năm kinh nghiệm, Con Rùa Biển đã nhận được sự tin tưởng tuyệt đối của các công ty, doanh nghiệp và cả khách hàng cá nhân.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold; font-size: 14px;\\\">Đa dạng dịch vụ vận tải đáp ứng mọi nhu cầu</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">Vận tải Con Rùa Biển đáp ứng mọi nhu cầu vận chuyển từ hàng nhỏ lẻ, đến hàng có khối lượng lớn, hàng siêu trường, siêu trọng với đa dạng các dịch vụ nổi bật:</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/chanh-xe-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Chành xe đi Phú Quốc</a>: Nhận vận chuyển hàng hóa từ Sài Gòn đi Phú Quốc hoặc Nhận vận chuyển hàng hóa từ Hà Nội đi Phú Quốc và nhiều khu vực khác trên cả nước đi Phú Quốc với nhiều hình thức khác nhau từ đường bộ, đường biển cho tới hàng không.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/cho-thue-xe-dau-keo-xe-container/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Dịch vụ cho thuê xe đầu kéo, xe container, vận chuyển container đi Phú Quốc:</a><span>&nbsp;</span>với thời gian vận chuyển nhanh chóng chỉ trong 1 ngày cho tuyến Sài Gòn - Phú Quốc, với nhiều dịch vụ Cho thuê đầu kéo sàn 12m, nhận vận chuyển container đi Phú Quốc từ Cảng Cát Lái, Cảng Vict, Cảng Đồng Nai và các Khu vực khác đi Phú Quốc, Hòn Thơm, Đảo Nam Du.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/cho-thue-xe-tai-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Dịch vụ cho thuê xe tải đi Phú Quốc:</a><span>&nbsp;</span>với nhiều loại xe với trọng tải khác nhau, đặc biệt là có xe chuyên dụng chở hàng quá khổ, quá tải đi Phú Quốc. Cho thuê xe tải 15 tấn, Cho thuê xe tải 20 tấn đi Phú Quốc.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/dich-vu-van-chuyen-hang-nho-le-hang-ghep/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Dịch vụ vận chuyển hàng nhỏ lẻ, hàng ghép</a><span>&nbsp;</span>đi Phú Quốc để tối ưu chi phí vận chuyển và có thời gian giao nhận rất nhanh. Cho dù là một thùng hàng nhỏ lẻ, Chúng tôi vận nhận và cung cấp dịch vụ tốt nhất có thể.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/dich-vu-cho-thue-xe-cau/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Dịch vụ cho thuê xe cẩu tại Phú Quốc</a>: Hỗ trợ bốc xếp hàng hóa, rút cont, hạ hàng hay lắp đặt các công trình xây dựng. Con Rùa Biển có đa dạng các loại xe cẩu từ 2,5 tấn cho đến 75 tấn phục vụ 24/24h.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">+<span>&nbsp;</span><a href=\\\"https://conruabien.vn/dich-vu-chinh/dich-vu-van-tai-hang-hoa-bac-nam/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Dịch vụ vận tải hàng hóa Bắc Nam</a>: Phục vụ nhu cầu vận chuyển hàng hóa xuyên quốc gia của khách hàng với mức giá ưu đãi nhất. Nhận vận chuyển hàng hóa từ Hà Nội đi Phú Quốc hoặc vận chuyển hàng từ Hà Nội đi Sài Gòn, Đồng Nai, Bình Dương, Long An, Cần Thơ và nhiều tỉnh khác.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">Bên cạnh các dịch vụ chính thì Vận tải Con Rùa Biển còn cung cấp đầy đủ các dịch vụ mở rộng để hỗ trợ quá trình vận chuyển hàng hóa dễ dàng, thông suốt bao gồm:</span></p><ul style=\\\"list-style-type: circle;\\\"><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/boc-xep-hang-hoa/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ Bốc xếp hàng hóa tại chỗ</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/dich-vu-dong-kien-go/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ đóng kiện gỗ bảo quả hàng hóa</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/cho-thue-kho-bai/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ cho thuê kho bãi</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/van-chuyen-duong-hang-khong/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ vận chuyển đường hàng không</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/van-chuyen-hang-hoa-duong-bien/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ vận chuyển đường biển</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/van-chuyen-duong-sat/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ vận chuyển đường sắt</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/cho-thue-sa-lan-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ cho thuê xà lan</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/khai-hai-quan-hang-nhap/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ khai hải quan hàng nhập</span></a></span></li><li style=\\\"margin-left: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"https://conruabien.vn/dich-vu-mo-rong/chuyen-phat-nhanh-quoc-te/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; font-size: 14px;\\\">Dịch vụ chuyển phát nhanh quốc tế</span></a></span></li></ul><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold; font-size: 14px;\\\">Vận tải Con Rùa Biển luôn đúng hẹn - an toàn và tiết kiệm</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\">Luôn phục vụ khách hàng với Tâm và Tín và luôn tìm giải pháp để mang đến những dịch vụ tốt nhất cho khách hàng, Vận tải Con Rùa Biển cam kết:</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">- Vận chuyển nhanh chóng, giao hàng đúng hẹn:<span>&nbsp;</span></strong>Với quy trình giao nhận chuyên nghiệp, phương tiện vận chuyển đầu tư hiện đại, tân tiến sẽ giúp cập nhật chi tiết lịch trình, kiểm soát thời gian giao hàng; Vận chuyển vào tất cả các ngày trong tuần, trực tiếp giao nhận nên luôn đảm bảo thời gian sớm nhất, đúng hẹn theo yêu cầu của quý khách hàng.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">- An toàn giảm tối thiểu hư hại hàng hóa:<span>&nbsp;</span></strong>Đội ngũ nhân viên ch­­uyên nghiệp cùng quy trình đóng gói hàng hóa cẩn thận từ những chi tiết nhỏ nhất sẽ đảm bảo hàng hóa của bạn được nguyên vẹn trong quá trình vận chuyển. Đồng hời hàng hoá được mua bảo hiểm nên công ty sẽ hoàn toàn chịu mọi trách nhiệm khi có thiệt hại xảy ra.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0); font-size: 14px;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">- Mức giá hợp lý:<span>&nbsp;</span></strong>Từ giá cước xe tải cho đến giá cước của các chành xe, là mức giá phù hợp để hợp tác lâu dài với khách hàng. Cam kết cạnh tranh nhất thị trường, không tăng giá mùa cao điểm và luôn có chương trình ưu đãi, hạ phí vận chuyển cho khách hàng.<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><a href=\\\"https://conruabien.xyz/bang-gia-van-tai-hang-hoa/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">(Click xem bảng giá vận chuyển hàng hóa ở tuyến đường và khu vực khác TẠI ĐÂY)</a></strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; text-align: justify; color: rgba(0, 0, 0, 0.62);\\\"><span style=\\\"box-sizing: border-box; font-family: arial, helvetica, sans-serif; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold; font-size: 14px;\\\">Bạn có nhu cầu vận chuyển hàng hóa đi Phú Quốc hay khắp mọi miền đất nước hãy liên hệ ngay hotline 094 500 00 06 để được tư vấn hỗ trợ tận tình, chu đáo nhất.</strong></span></p></div></div></div></div></div><div class=\\\"fl-col fl-node-5ba99e264490c fl-col-small\\\" data-node=\\\"5ba99e264490c\\\" style=\\\"box-sizing: border-box; zoom: 1; float: left; min-height: 1px; width: 530px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><div class=\\\"fl-col-content fl-node-cont