y\\\" width=\\\"1024\\\" height=\\\"768\\\" class=\\\"uabb-photo-img wp-image-639\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/03/DICH-VU-VAN-CHUYEN-HANG-HOA-BAC-NAM-DUONG-DAI-TU-SAI-GON-DI-HA-NOI.jpg\\\" alt=\\\"(Ảnh: vận chuyển hàng hóa bắc nam, cty Con Rùa Biển nhận vận chuyển hàng hóa đường dài tại bãi xe HCM)\\\" itemprop=\\\"image\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/03/DICH-VU-VAN-CHUYEN-HANG-HOA-BAC-NAM-DUONG-DAI-TU-SAI-GON-DI-HA-NOI.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/03/DICH-VU-VAN-CHUYEN-HANG-HOA-BAC-NAM-DUONG-DAI-TU-SAI-GON-DI-HA-NOI-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: content-box; height: auto; max-width: 100%; border: 0px; vertical-align: middle; display: inline; width: auto; border-radius: inherit; box-shadow: none;\\\"></div></div></div></div></div></div></div>\"',NULL,'/gioi-thieu',NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (125,4,'Cho Thuê Xà Lan Chở Hàng Hóa','Ở những nơi xa, đường bộ chưa có, Chúng tôi sẽ kết hợp cả đường thủy','https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-21.jpg','\"<p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">banggia=88</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">banggia=89</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">Để hỗ trợ tối đa cho các dịch vụ vận tải đường biển, đường bộ hay hàng không, Công ty TNHH Dịch vụ Hàng hóa Con Rùa Biển cung cấp tới khách hàng các dịch vụ hỗ trợ. Một trong số đó là cho thuê sà lan (<a data-mil=\\\"35\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/cho-thue-sa-lan-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(0, 0, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">cho thuê xà lan</strong></a>) với mức giá ưu đãi, đảm bảo an toàn nhất.</span></p><div id=\\\"attachment_1331\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1331\\\" decoding=\\\"async\\\" class=\\\"wp-image-1331 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-16.jpg\\\" alt=\\\"(ảnh dịch vụ mở rộng Cho thuê xà lan, cho thuê sà lan )\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-16.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-16-768x432.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1331\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; font-family: &quot;times new roman&quot;, times, serif; color: rgb(0, 0, 0); font-size: 12pt;\\\">(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm, các xe đầu kéo bắt đầu leo con dốc đầu tiên trên đảo Hòn Thơm)</span></p></div><div id=\\\"attachment_840\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-840\\\" decoding=\\\"async\\\" class=\\\"wp-image-840 size-full\\\" title=\\\"cho thuê sà lan - cho thuê tàu biển; hình ảnh vận chuyển container hàng hóa bằng sà lan đang đi trên sông Sài Gòn\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-14.jpg\\\" alt=\\\"(ảnh dịch vụ mở rộng Cho thuê xà lan, cho thuê sà lan )\\\" width=\\\"1024\\\" height=\\\"662\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-14.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-14-768x497.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-840\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">(Ảnh: cho thuê sà lan – cho thuê tàu biển; hình ảnh vận chuyển container hàng hóa bằng sà lan đang đi trên sông Sài Gòn)</span></p></div><h1 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; font-size: 18pt; font-family: &quot;times new roman&quot;, times, serif; color: rgb(0, 0, 0);\\\">Dịch vụ cho thuê Xà lan hỗ trợ vận chuyển hàng hóa TỐT NHẤT, giá cả cạnh tranh nhất</span></h1><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">Tại Việt Nam, nhất là ở các tỉnh miền Tây Nam bộ với hệ thống sông ngòi chằng chịt chính là điều kiện để vận chuyển bằng sà lan phát triển. Những chiếc sà lan giúp hàng hóa được lưu thông dễ dàng, đến được với nhiều nơi, cả ở vùng sâu, vùng xa.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\">Chính vì vậy, nhu cầu vận chuyển thuê sà lan của các công ty, doanh nghiệp và cá nhân là rất lớn. Hơn nữa đây là dịch vụ hỗ trợ đắc lực cho các tuyến vận tải đường biển hay đường bộ. Đây là những lí do thúc đẩy<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận tải hàng hóa Con Rùa Biển</strong><span>&nbsp;</span>đưa<span>&nbsp;</span><a data-mil=\\\"35\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/cho-thue-sa-lan-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(0, 0, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">dịch vụ cho thuê sà lan</strong></a><span>&nbsp;</span>đến với khách hàng.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 12pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ vận chuyển cho thuê sà lan</strong><span>&nbsp;</span>từ TP.Hồ Chí Minh đi các tỉnh miền Tây, đồng bằng sông Cửu Long của Con Rùa Biển luôn đáp ứng đầy đủ các tiêu chí như an toàn, hiệu quả, tiết kiệm chi phí và thời gian.</span></p><div id=\\\"attachment_839\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-839\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-839 size-full\\\" title=\\\"(Ảnh: cho thuê sà lan - cho thuê tàu biển; hình ảnh Công ty Con Rùa Biển vận chuyển hàng hóa là thiết bị cáp treo, đang bốc xếp hàng từ trên cảng tại HCM đưa xuống sà lan để vận chuyển ra đảo Phú Quốc)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-13.jpg\\\" alt=\\\"(ảnh dịch vụ mở rộng Cho thuê xà lan, cho thuê sà lan )\\\" width=\\\"1024\\\" height=\\\"683\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-13.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/HINH-ANH-CHO-THUE-XA-LAN-CHO-THUE-PHA-CHO-THUE-TAU-BIEN-13-768x512.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-839\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times n