INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (127,4,'Cho Thuê Công Nhân Bốc Xếp Hàng Hoá','Nhận bốc xếp các loại hàng hóa tại các công trình ở Phú Quốc - cho thuê xe cẩu','https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-17.jpg','\"<h1 style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">DỊCH VỤ BỐC XẾP HÀNG HÓA NHANH CHÓNG, AN TOÀN, TIẾT KIỆM</strong></span></h1><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đối với những hàng hóa cồng kềnh, khối lượng lớn thì việc bốc xếp muốn dễ dàng, nhanh chóng cần sự hỗ trợ của máy móc cũng như số lượng công nhân đông. Vì thế, để đáp ứng nhu cầu của khách hàng, Vận tải Con Rùa Biển cung cấp dịch vụ<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"42\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/boc-xep-hang-hoa/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">bốc xếp hàng hóa</strong></a></span><span>&nbsp;</span>tại chỗ an toàn, tiết kiệm.</span></p><div id=\\\"attachment_673\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-673\\\" decoding=\\\"async\\\" class=\\\"wp-image-673 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-14.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-14.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-14-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-673\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận vận chuyển và bốc xếp các loại hàng hóa, khi bốc xếp sẽ luôn được bộ phận sắp xếp theo trình tự nhất định và đạt tiêu chuẩn an toàn cty đã đề ra, đảm bảo cho khách hàng được yên tâm khi gửi hàng qua hệ thống Con Rùa Biển)</span></p></div><div id=\\\"attachment_660\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-660\\\" decoding=\\\"async\\\" class=\\\"wp-image-660 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-1.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"576\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-1.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-1-768x432.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-660\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận rút hàng Đá Hoa Cương trong container để sang qua xe tải, sau đó nhận vận chuyển Đá Hoa Cương đi từ HCM ra Đảo Phú Quốc bằng xe tải mui bạc)</span></p></div><h1><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Bốc xếp hàng hóa bằng máy móc hiện đại</strong></span></h1><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Việc vận chuyển hàng hóa đi đến nơi, về đến chốn an toàn không đảm bảo 100% là món hàng của bạn nguyên vẹn, không bị hỏng hóc nếu việc bốc xếp không đảm bảo. Nhất là đối với các loại hàng hóa cồng kềnh khối lượng lớn như thiết bị máy móc, hàng công nghiệp, sắt thép, hàng công trình xây dựng…</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đối với những loại hàng hóa này nếu bốc xếp bằng sức người sẽ rất tốn thời gian, chi phí, và nhiều trường hợp bắt buộc phải sử dụng đến máy móc. Bởi vậy, ngoài việc vận chuyển thì Công ty TNHH Dịch vụ Hàng hóa Con Rùa Biển còn cung cấp dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">bốc xếp hàng hóa</strong>, rút cont, hạ hàng bằng xe cẩu với ưu điểm vượt trội:</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Nhanh chóng:<span>&nbsp;</span></strong>Hàng hóa khi được vận chuyển tới bến cảng hay điểm tập kết sẽ có các loại xe chuyên dụng tại chỗ để bốc dỡ ngay. Việc sử dụng máy móc giúp tăng năng suất, dễ dàng bốc dỡ hàng hóa cồng kềnh, trọng lượng lớn, tiết kiệm thời gian.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">An toàn:<span>&nbsp;</span></strong>Việc rút cont hay hạ hàng bằng thiết bị chuyên dụng sẽ hạn chế rủi ro tối đa, không để hàng hóa bị xô lệch, rơi rớt hay va chạm… đảm bảo nguyên trạng như ban đầu.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Tiết kiệm:</strong><span>&nbsp;</span>Với việc sử dụng dịch vụ vận chuyển và bốc xếp hàng hóa trọn gói của Vận tải Con Rùa Biển, khách hàng sẽ tiết kiệm được chi phí so với việc thuê đơn vị bốc xếp bên ngoài. Bên cạnh đó, Con Rùa Biển cũng thường xuyên có các chương trình khuyến mãi, ưu đãi riêng cho khách hàng thân thiết.</span></li><li style=\\\"box-sizing: border-box;\\\"><br></li></ul><div id=\\\"attachment_661\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-661\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-661 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-2.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-2.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-2-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-661\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận bố xếp Dàn Giáo từ xe tải vào trong kho tại công trình Đảo Phú Quốc)</span></p></div><div id=\\\"attachment_662\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-662\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-662 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-3.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-3.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-3-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-662\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận rút hàng Gỗ Trang Trí trong container để sang qua xe tải, sau đó nhận vận chuyển Gỗ Trang Trí này đi từ HCM ra Đảo Phú Quốc bằng xe tải mui bạc)</span></p></div><div id=\\\"attachment_664\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-664\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-664 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-5.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"1365\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-5.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-5-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-664\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận vận chuyển hàng Đá Hoa Cương từ Sài Gòn ra Phú Quốc sau đó được xe cẩu hạ hàng từ xe tải xuống đất tại chân công trình Dương tơ, Phú quốc)</span></p></div><div id=\\\"attachment_665\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-665\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-665 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-6.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"1446\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-6.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-6-768x1085.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-665\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển nhận Bốc xếp hàng ỐNG NHỰA từ Sài Gòn đi Hòn Thơm, sau đó đưa hàng vào tận chân công trình)</span></p></div><div id=\\\"attachment_666\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-666\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-666 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-7.jpg\\\" alt=\\\"(Ảnh Dịch Vụ Mở Rộng: Bốc xếp hàng hóa)\\\" width=\\\"1024\\\" height=\\\"576\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-7.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/Hinh-anh-boc-xep-hang-hoa-tai-Phu-Quoc-cho-thue-nhan-cong-HCM-7-768x432.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-666\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Bốc xếp hàng hóa, Cty Con Rùa Biển bốc xếp miễn phí các loại hàng hóa tại chành xe để hỗ trợ khách hàng, có nhân viên kiểm điếm và tính giá vận chuyển cẩn thận ngay khi gửi hàng)</span></p></div><p><h1 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: 0px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Đội ngũ công nhân Bốc xếp hàng hóa chuyên nghiệp, “hùng hậu”</strong></span></h1></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Việc bốc xếp hàng hóa không chỉ có máy móc mà còn phải có đội ngũ nhân sự là các công nhân chuyên nghiệp với sức khỏe tốt, thái độ làm việc trách nhiệm và có kinh nghiệm:</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Điều khiển máy móc: Để vận hành các loại xe cẩu, xe nâng rút cont hay bốc xếp hàng hóa thì đội ngũ các công nhân phải được đào tạo bài bản, điều khiển máy móc với thao tác chính xác, thuần thục, nhanh chóng</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hỗ trợ bốc xếp ở những nơi chật hẹp, đông đúc, hàng hóa nhỏ lẻ: Khi khách hàng có nhu cầu bốc xếp, dỡ hàng hóa đến khu vực mà xe tải hay phương tiện máy móc không thể hoạt động, khu dân cư, hay khối lượng hàng nhỏ thì Vận tải Con Rùa Biển cũng luôn sẵn sàng đội ngũ công nhân sức khỏe tốt để đáp ứng.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Bốc xếp tận nơi: Trong quá trình vận chuyển, khách hàng không có người bốc xếp, Vận tải Con Rùa Biển sẽ hỗ trợ tận nơi hoặc khi hàng ra bãi xe, đến điểm giao hàng cũng sẽ có nhân viên bốc xếp tại chỗ. Tất cả các mặt hàng của khách hàng sẽ được các nhân viên tại công ty thực hiện bốc, dỡ và xếp hàng trước khi vận chuyển.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Vận tải Con Rùa Biển có quy trình rõ ràng xác định số lượng, khối lượng, kích thước hàng hóa để đưa ra phương án bốc xếp khoa học, hợp lý, tiết kiệm nhất. Hàng hóa cũng luôn được đóng gói cẩn thận, di chuyển an toàn, nhanh chóng. Đặc biệt, trong quá trình bốc xếp nếu hàng hóa bị tổn hại, Con Rùa Biển hoàn toàn chịu trách nhiệm.</span></li></ul><div id=\\\"attachment_3795\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-3795\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3795\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-3-scaled.jpg\\\" alt=\\\"Van chuyen da hoa cuong di Phu Quoc 3 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-3-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-3-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-3-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-3-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3795\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Đá Hoa Cương đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh xe tải cẩu chở Đá Hoa Cương đến chành xe Con Rùa Biển HCM để vận chuyển đá hoa cương đi Phú Quốc bằng hình thức ghép xe tải, tiết kiệm chi phí khi đi số lượng vài tấn đá hoa cương ra đảo Phú Quốc)</p></div><div id=\\\"attachment_3662\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3662\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3662\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-42.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 42\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-42.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-42-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-42-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-42-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3662\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất của Khách hàng đem ra chành xe Phú Quốc tại HCM, để gửi hàng nội thất đi Phú Quốc theo hình thức đi ghép xe tải cùng với nhiều loại hàng hóa khác để tiết kiệm chi phí vận chuyển, đây là hình thức đi ghép phổ biến nhất hiện nay tại chành xe chuyến tuyến đi Phú Quốc, và cũng cứ mỗi buổi chiều hằng ngày anh em công nhân của bãi xe đã xếp hàng hóa các loại lên xe tải để đi ghép qua phú quốc hằng ngày, hằng ngày bắt đầu xếp hàng lên xe từ lúc chiều cho đến nữa đêm hay đến khi nào xong hàng mới nghĩ)</p></div><div id=\\\"attachment_667\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-667