INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (160,2,'Nhận vận chuyển hàng lẻ từ Cảng HCM đi Phú Quốc | 0945000006','Tìm đơn vị Nhận vận chuyển hàng lẻ từ Cảng HCM đi Phú Quốc cần chú ý điều gì? Bạn muốn tìm đơn vị Nhận vận chuyển hàng lẻ từ Cảng HCM đi Phú Quốc uy tín, chất lượng với giá cước tốt nhất. Nhưng đứng trước rất nhiều sự lựa thì bạn phải làm…','https://conruabien.vn/wp-content/uploads/2023/02/van-chuyen-hang-bot-tret-di-phu-quoc-gia-re-5-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tìm đơn vị Nhận vận chuyển hàng lẻ từ Cảng HCM đi Phú Quốc cần chú ý điều gì?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;