INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (232,14,'Dự án Vận chuyển 5 Container thiết bị đi Hòn Thơm','Vận chuyển Container đi Hòn Thơm Phú Quốc có khó không? Hiện nay việc vận chuyển máy móc thiết bị hay vận chuyển vật tư công trình đi đường bộ Bắc Nam bằng xe tải đã là khó khăn…','https://conruabien.vn/wp-content/uploads/2021/05/%E1%BA%A2nh-b%C3%ACa-D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m.jpg','\"<h1 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-weight: normal !important; font-size: 30px;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc có khó không?</h1><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hiện nay việc<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển máy móc thiết bị</strong><span>&nbsp;</span>hay<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển vật tư công trình đi đường bộ Bắc Nam bằng xe tải</strong><span>&nbsp;</span>đã là khó khăn. Nhưng còn đây là việc<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"1345\\\" href=\\\"https://conruabien.vn/du-an-da-van-chuyen/du-an-van-chuyen-5-container-thiet-bi-di-hon-thom/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc</strong></a><span>&nbsp;</span></span>thì chắc chắn là điều không hề dễ dàng</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc&nbsp;</strong>sẽ vô cùng khó khăn vì không phải bất kỳ nhà xe nào cũng có thể vận chuyển container đi ra đảo được, vì có đôi khi nhà xe đó còn chưa biết đến đảo Hòn Thơm nằm ở đâu thì làm sao mà nói đến việc vận chuyển hàng hóa thiết bị hay<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc&nbsp;</strong>cho an toàn và giá rẻ.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc&nbsp;</strong>không những đi qua biển bằng phà tại Hà Tiên mà còn đi qua đảo đến 2 lần đi phà biển chuyên dụng, tức là<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">phà chở xe đầu kéo container đi trên biển</strong><span>&nbsp;</span>để qua được đảo Hòn Thơm Phú Quốc.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Mà muốn<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc&nbsp;</strong>thì trước đó phải đi<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">phà vận chuyển xe container đi Phú Quốc</strong><span>&nbsp;</span>trước khi<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm.</strong></span></p><div id=\\\"attachment_1318\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-1318\\\" decoding=\\\"async\\\" class=\\\"wp-image-1318 size-full\\\" title=\\\"(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-3.jpg\\\" alt=\\\"(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm) vận chuyển Container đi Hòn Thơm Phú Quốc\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-3.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-3-768x432.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1318\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm)</span></p></div><h1 id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify; font-weight: normal !important; font-size: 30px;\\\">Một số vấn đề cần được quan tâm khi<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc</strong></h1><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Một công trình mang tầm cỡ quốc tế trên một hòn đảo nhỏ ngoài khơi lại hoành tráng và lung linh như thế được xây dựng như thế nào?</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify; font-size: 14px;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Vận chuyển hàng hóa, nội thất, máy móc, trang thiết bị vật tư công trình ra đảo Hòn Thơm bằng cách nào?</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Xe tải có<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">chở hàng hóa đi Hòn Thơm Phú Quốc</strong><span>&nbsp;</span>được hay không?</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Xe đầu kéo container có qua đảo Hòn Thơm được hay không?</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Chi phí vận chuyển đi Hòn Thơm</strong><span>&nbsp;</span>có mắc không?</span></li><li style=\\\"box-sizing: border-box;\\\">Thời gian<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển Container đi Hòn Thơm Phú Quốc&nbsp;</strong>mất bao lâu?</li></ul><div id=\\\"attachment_1344\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-1344\\\" decoding=\\\"async\\\" class=\\\"wp-image-1344 size-full\\\" title=\\\"(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe Phà chuyên dụng chở Container đi trên biển để đến đảo Hòn Thơm, cả xe đầu kéo và container cùng lên phà để qua đảo còn nguyên seal)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-28.jpg\\\" alt=\\\"(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm) vận chuyển Container đi Hòn Thơm Phú Quốc\\\" width=\\\"2400\\\" height=\\\"1657\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-28.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-28-768x530.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-