INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (237,14,'Dự Án vận chuyển Thiết Bị Cáp Treo đi Hòn Thơm, Phú Quốc','Dự Án vận chuyển Thiết Bị Cáp Treo đi Hòn Thơm, Phú Quốc Cáp treo là gì? Cáp treo (tiếng Anh: aerial tramway, sky tram, cable car) là một loại phương tiện di chuyển trên không sử dụng một hoặc hai dây cố định để gắn vào…','https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-21.jpg','\"<h1 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-size: 36px; margin: 20px 0px 10px; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dự Án<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/du-an-da-van-chuyen/du-an-van-chuyen-thiet-bi-cap-treo-hon-thom-dai-nhat-the-gioi-tai-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">vận chuyển Thiết Bị Cáp Treo</a></span><span>&nbsp;</span>đi Hòn Thơm, Phú Quốc</span></h1><h2 id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cáp treo là gì?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cáp treo</strong>&nbsp;(tiếng Anh: aerial tramway, sky tram, cable car) là một loại phương tiện di chuyển trên không sử dụng một hoặc hai dây cố định để gắn vào, kèm theo một dây thứ ba để đẩy. Với hình thức này, cáp treo trên không luôn cố định vào dây và không thể tách rời khỏi trong suốt quá trình vận hành.</span></p><h2 id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hòn Thơm là ở đâu? Hòn Thơm nằm ở Vị trí nào?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Hòn Thơm, Phú Quốc</strong><span>&nbsp;</span>là điểm đến được rất nhiều khách du lịch trong và ngoài nước lựa chọn. Với nhiều hòn đảo nhỏ liền kề, Phú Quốc được được mệnh danh là hòn Đảo Ngọc. Phú Quốc là hòn đảo lớn nhất của nước ta nằm trong quần thể 22 hòn đảo nơi đây.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Với tốc độ phát triển kinh tế chóng mặt, Đảo Phú Quốc sẽ trở thành một trong những thành phố nỗi tiếng trên thế giới trong tương lai.</span></p><div id=\\\"attachment_811\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-811\\\" decoding=\\\"async\\\" class=\\\"wp-image-811 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-19.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"1365\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-19.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-19-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-811\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Cơ sở xây dựng hạ tầng dầy đặc, nên hiện nay việc vận chuyển hàng hóa đi Phú Quốc là một trong những vấn đề quan trọng của các đơn vị thi công công trình, cũng như là các doanh nghiệp cung cấp dịch vụ và sản xuất … cần đem hàng hóa ra đảo Phú Quốc</span></p><h2 id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Con Rùa Biển hiện tại đang cung cấp dịch vụ gì?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nhận biết được điều này nên Công ty vận tải hàng hóa Con Rùa Biển đã sớm triển khai dịch vụ vận tải hàng hóa ra đảo Phú Quốc, với nhiều loại hình dịch vụ đa dạng</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; list-style-type: circle;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"http://vantainoidia.vn/dich-vu/chanh-xe-van-chuyen-hang-hoa-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Chành xe đi Phú Quốc</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/cho-thue-xe-dau-keo-xe-container/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe đầu kéo, xe container đi Phú Quốc</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/cho-thue-xe-tai-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe tải đi Phú Quốc</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/dich-vu-van-chuyen-hang-nho-le-hang-ghep/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ vận chuyển hàng nhỏ lẻ, hàng ghép đi Phú Quốc</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/dich-vu-cho-thue-xe-cau/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe cẩu tại Phú Quốc</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"http://vantainoidia.com.vn/dich-vu/van-tai-duong-bo/chanh-xe-van-chuyen-hang-hoa-cac-tinh-di-mien-bac.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ vận tải hàng hóa Bắc Nam</strong></a></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Bốc xếp hàng hóa</strong><span>&nbsp;</span>tại chỗ (tại công trình) ở Phú Quốc</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><a data-mil=\\\"44\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/dich-vu-dong-kien-go/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(0, 0, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\">đóng kiện gỗ</span></strong></a><span>&nbsp;</span>bảo quả hàng hóa trong quá trình vận chuyển hàng đi Phú Quốc</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">cho thuê kho bãi</strong><span>&nbsp;</span>chứa hàng hóa ở Phú Quốc miễn phí ngắn hạn.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển đường hàng không đi Phú Quốc</strong></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển đường biển đi Phú Quốc</strong></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa đường sắt Bắc Nam</strong></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">cho thuê xà lan đi Phú Quốc</strong><span>&nbsp;</span>và các tỉnh miền tây</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">khai hải quan hàng nhập</strong></span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">chuyển phát nhanh</strong><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">đi Phú Quốc</strong></span></li></ul><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ngoài những dịch vụ cung cấp bên trên Chúng tôi còn hỗ trợ Quý khách hàng lấy hàng tận nơi(tất cả các tỉnh trên cả nước), giao hàng tận nơi ở Phú Quốc (Dương Đông, AnThới, Dương Tơ, Cửa Cạn, Gành Dầu, Cửa Dương, Bãi Thơm, Hòn Thơm, Hàm Ninh, Thổ Châu…)</span></p><div id=\\\"attachment_810\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-810\\\" decoding=\\\"async\\\" class=\\\"wp-image-810 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-18.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-18.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-18-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-810\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-5\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị Cáp treo có khó không?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị Cáp treo</strong><span>&nbsp;</span>chắc chắn sẽ có rất nhiều khó khăn trong quá trình vận chuyển, đặc biệt ở đây Cáp treo thường được đặc ở ví trí núi cao hoặc ngoài biển đảo nên cung đường vận tải là cả một vấn đề lớn.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nếu đối với những đơn vị chưa bao giờ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển thiết bị cáp treo</strong><span>&nbsp;</span>mà khi đi khảo sát thì chỉ có nước bỏ cuộc đi về thôi chứ làm sao mà bao giá cho được, vì ở đây đường đi toàn là đồi núi, rừng rậm hoặc là một bờ biển bao là hoặc là một ngon núi ở giữa một hòn đảo nhỏ ngoài khơi.</span></p><div id=\\\"attachment_812\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-812\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-812 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-20.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-20.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-20-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-812\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-6\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo cần chú ý những gì?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị Cáp treo<span>&nbsp;</span></strong>cần phải chú ý đến “cung đường vận chuyển của thiết bị”, đây là một công việc hết sức quan trọng, vì có những nơi không thể đi được bằng phương tiện vận chuyển thông thường.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tiếp theo là<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">trọng lượng của thiết bị cáp treo<span>&nbsp;</span></strong>cũng quan trọng không kém, bởi vì nếu nặng quá thì không thể nào vận chuyển được ở các cung đường cong hoặc dốc cao quá, thì những kiện hàng có trọng lượng lớn vài chục tấn thì phải tính toán rất kỹ lượng mới có phương án phù hợp nhất.</span></p><div id=\\\"attachment_809\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-809\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-809 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-17.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-17.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-17-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-809\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-7\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Loại xe nào có thể vận chuyển thiết bị cáp treo được một cách tốt nhất?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Có rất nhiều thiết bị chuyên dụng cho việc vận chuyển bắt buộc phải có mới sử dụng được cho trong quá trình<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển thiết bị cáp treo</strong>:</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo</strong><span>&nbsp;</span>bằng xe tải: xe tải loại 15 tấn, xe tải loại 20 tấn hoặc xe tải nhỏ 2 tấn, xe tải nhỏ nhỏ thì dùng để trung chuyển trong nội bộ công trình, vì sẽ có rất nhiều thiết bị nhỏ lẻ cần di chuyển liên tục.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo</strong><span>&nbsp;</span>bằng xe cuốc. Oh xe cuốc mà cũng vận chuyển nữa à! thật sự không phải vậy, xe cuốc ở đây là được dùng để kéo xe tải khi lên dốc không nỗi, thì xe cuốc là người đi tiên phong. Rất tối ưu ở những cung đường có độ dốc cao.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị bằng xe ben:<span>&nbsp;</span></strong>ở những nơi có độ dóc quá cao xe tải không thể di chuyển được nữa, thì xe ben là phương án tối ưu tiếp theo được lựa chọn</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo bằng xe đầu kéo container thùng kín</strong>: hàng hóa khi nhập về từ nước ngoài sẽ được thông quan tại HCM, sau đó được xe đầu kéo kéo nguyên container nguyên seal đến tận chân công trình.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo bằng xe đầu kéo rơ mooc lùn chuyên dụng</strong><span>&nbsp;</span>để chở hàng quá khổ quá tải.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo bằng xà lan (tàu biển)</strong><span>&nbsp;</span>được áp dụng cho các dự án cáp treo nằm ngoài biển, thì hình thức vận chuyển đa phương thức bắt buộc phải được áp dụng.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo bằng máy bay</strong><span>&nbsp;</span>cũng là một trong những phương án được tính đến nếu như tất cả các phương án đường sông, đường bộ, đường biển điều không khả thi thì phương án máy bay sẽ được áp dụng cho dự án.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị cáp treo bằng xe cẩu</strong><span>&nbsp;</span>là một trong những phương tiên không thể thiết trong bất kỳ một dự án vận chuyển cáp treo nào. Vì toàn bộ hàng thiết bị cáp treo điều là mặt hàng nặng nên tất cả phải được sử dụng phương tiện xe cẩu, xe cẩu kato 25 tấn, kato 45 tấn … hoặc xe cẩu thùng 15 tấn, xe cẩu thùng 20 tấn …</span></li></ul><div id=\\\"attachment_808\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-808\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-808 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-16.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-16.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-16-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-808\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-8\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Công ty vận chuyển thiết bị máy móc giá trị cao nào là tốt nhất và uy tín nhất thị trường hiện nay?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hiện nay việc vận chuyển thiết bị hạng nặng thì có rất nhiều công ty trên thị trường làm được và làm tốt, nhưng nếu nói về chuyên<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển thiết bị cáp treo</strong><span>&nbsp;</span>thì sẽ còn lại rất ít đơn vị vận chuyển được mặt hàng cáp treo này, vì rất nhiều lý do, như là không có đủ phương tiện chuyên dụng để vận hành phương pháp vận tải đa phương thức, hay là nguồn nhân lực nhiều kinh nghiệm trong lĩnh vực vận chuyển thiết bị máy móc.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Con Rùa Biển là một trong những công ty được nhắc đến trong lĩnh vực<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển thiết bị cáp treo</strong>, trong đó nỗi bật là dự án vận chuyển thiết bị cho DỰ ÁN CÁP TREO HÒN THƠM, đây được coi là một trong những dự án cáp treo có chiều dài lớn nhất thế giới được vận hành tại Việt Nam hiện nay.</span></p><div id=\\\"attachment_807\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-807\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-807 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-15.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-15.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-15-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-807\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><div id=\\\"attachment_796\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-796\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-796 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-4.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-4.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-4-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-796\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là nhân công móc dây xích để đưa thiết bị xuống tàu, xà lan)</span></p></div><h2 id=\\\"ftoc-heading-9\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị máy móc hạng nặng ở công ty nào để có được chi phí vận chuyển rẻ nhất?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đối với việc vận chuyển máy móc thiết bị thì ở hầu hết các đơn vị vận chuyển không bao giờ có chung một mức giá, mỗi một đơn vị vận chuyển khác nhau họ có một công thức tính giá khác nhau, từ đó sẽ có rất nhiều mức giá khác nhau.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đặc biệt hơn nữa, ở một công ty thôi cũng có thể đưa ra nhiều mức giá khác nhau để cho khách hàng lựa chọn, chính vì điều đó để nói mức giá ở đâu là rẻ nhất là điều không thể.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nhưng để biết được đâu là mức giá phù hợp nhất thì lại không khó lắm, cứ lấy sự chuyên nghiệp của các đơn vị vận chuyển mà làm căn cứ ban đầu để lựa chọn, sau đó cho vào sự lựa chọn của mình thêm một số tiêu chí riêng để lựa chọn, thì từ đó sẽ có được một đơn vị được gọi là phù hợp nhất để chốt giá cuối cùng.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hiện nay tại Con Rùa Biển thì đang tính giá vận chuyển cho mặt hàng giá trị cao như thiết bị máy móc là dựa theo kích thước hàng hóa, cân nặng và giá trị của lô hàng là bao nhiêu tiền, từ 3 thông tin cơ bản đó mà có mức giá phù hợp với yêu cầu của khách hàng. Giá vận chuyển hàng hóa tại Con Rùa Biển dựa vào tiêu chuẩn an toàn hàng hóa lên hàng đầu để áp giá, sau đó là tính đến trọng lượng, kích thước, đường gần hay xa, từ đó thông kế lại và tiến hành chốt đơn giá cuối cùng gửi đến khách hàng.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\">&nbsp;</p><div id=\\\"attachment_806\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-806\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-806 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-14.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-14.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-14-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-806\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh thiết bị bên trong container hàng nhập tại cảng Vict HCM trước khi rút cont đưa xuống tàu, xà lan để vận chuyển đi Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-10\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển thiết bị máy móc cáp treo từ Cảng Cát Lái đến Đảo Hòn Thơm, Phú Quốc bằng những hình thức vận chuyển nào?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dự án vận chuyển máy móc thiết bị cáp treo này đã được Con Rùa Biển áp dụng hình thức vận tải đa phương thức kết hơn giữa các phương tiện.</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Xe đầu kéo container đi đường bộ</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Phà đi biển (tàu biển) đưa xe container qua đảo</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Xe cẩu kato 45 tấn, xe cẩu kato 75 tấn nâng hạ hàng thiết bị máy móc.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Xe đầu kéo container rơ mooc sàn để trung chuyển hàng hóa thiết bị tại công trình.</span></li></ul><div id=\\\"attachment_794\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-794\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-794 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-2.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"1365\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-2.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-2-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-794\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là thiết bị cáp treo đã được xếp gần đầy tàu, làm việc từ ban ngày cho đến ban đêm để công trình kịp nhận hàng cho kịp tiến độ thi công tại Hòn Thơm, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-11\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Trong dự án vận chuyển Thiết bị Cáp treo này thì Con Rùa Biển đã sử dụng hình thức vận tải nào để áp dụng cho việc Vận chuyển thiết bị máy móc đến Hòn Thơm – Phú Quốc một cách an toàn nhất?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Trong dự án Vận chuyển thiết bị cáp treo này thì có rất nhiều đơn hàng vận chuyển đi trong một khoãng thời gian dài nhiều năm.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Trong đó có rất nhiều hinh thức vận tải khác nhau để áp dụng cho dự án lần này: kết hợp đường bộ + đường biển + đường bộ + cho đến cả phương án dùng xe cuốc với xe ben để leo núi giao hàng.</span></p><div id=\\\"attachment_795\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-795\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-795 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-3.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-3.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-3-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-795\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh đang đưa thiết bị xuống tàu, xà lan)</span></p></div><h2 id=\\\"ftoc-heading-12\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Thống kê tóm tắt bài viết về Dự án vận chuyển thiết bị cáp treo từ đất liền ra đến Đảo Hòn Thơm, Phú Quốc, Kiên Giang đã trải qua các công đoạn vận chuyển như thế nào?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đối với đợt hàng nhập nguyên container nguyên seal</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nhận hàng từ Cảng Cát Lái ở HCM</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dùng đầu kéo container 40f, hoặc đầu kéo container chuyên dụng để chuyển cont từ Sg đi Đến Hà Tiên, Kiên Giang</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Sau đó dùng Phà đi biển để đưa cả xe container và hàng di chuyển ngang biển</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khi xe container đã đến đảo thì sẽ chạy lên tận chân công trình để cho khách kiểm tra nguyên seal rồi thì mới giao</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tại nơi giao hàng ở công trình<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cáp Treo Hòn Thơm</strong><span>&nbsp;</span>sẽ được Con Rùa Biển điều xe cẩu kato chuyên dụng đến rút cont và hạ hàng vào vị trí đã được chỉ định.</span></li></ul><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ngoài ra còn có những chuyến hàng số lượng<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">thiết bị cáp treo</strong><span>&nbsp;</span>quá lớn thì bên Con Rùa Biển đã điều hẳn 1 vài chiếc tàu biển chuyên dụng để chở thiết bị về tận cảng ở sài gòn để nhận hàng.</span></p><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Rút container hàng tại Cảng HCM, đưa xuống tàu và chở hàng ra tận cảng ở ngoài đảo Phú Quốc, Kiên Giang (lúc này Con Rùa Biển áp dụng<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">giá cho thuê xà làn (tàu biển) đi Phú Quốc nguyên chiếc</strong>.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khi tàu đã cặp bến tại Cảng An Thới Phú Quốc, Kiên Giang sẽ được Con Rùa Biển điều động nhiều loại phương tiện chuyên dụng đến để trung chuyển thiết bị cáp treo về nhà kho của công trình.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đợt trung chuyển thiết bị cáp treo lần này gồm rất nhiều phương tiện đã được sử dụng để đẩy nhanh tốc độ giao nhận hàng hóa cho Sun Group.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dùng xe đầu kéo rơ mooc sàn để di chuyển hàng từ cảng về kho Nhà Ga Đi An Thới, Phú Quốc</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tại bên Cảng An Thới đã được bộ trí 2 xe cẩu kato 45 tấn để đưa hàng từ xà lan lên xe đầu kéo</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tại Nhà Gà Đi An Thới được bố trí xe cẩu thùng 20 tấn và xe cẩu kato 75 tấn để hạ hàng cho nhanh.</span></li></ul><div id=\\\"attachment_801\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-801\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-801 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-9.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-9.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-9-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-801\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh này cho thấy tàu đang được neo đậu tại bên cảng phú quốc, chuẩn bị đưa thiết bị lên bờ, còn cho thấy trụ cáp treo số 1 phía bờ An Thới, Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-13\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Khách hàng tìm đến Con Rùa Biển bằng cách nào?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hiện nay Khách hàng tìm đến Con Rùa Biển có rất nhiều hình thức như Quảng cáo, Gọi điện thoại, Người quen giới thiệu, hoặc đối tác hay nhà cung cấp dịch vụ … Nhưng khách hàng tìm đến dịch vụ vận chuyển của Con Rùa Biển là hình thức<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Khách hàng giới thiệu Khách hàng.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Trong dự án này cũng vậy, được sự tin tưởng của Quý Khách hàng mà Con Rùa Biển đã được nhận dự án vận chuyển lớn trong nhiều năm.</span></p><div id=\\\"attachment_800\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-800\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-800 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-8.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-8.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-8-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-800\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là hình được chụp tại đảo Phú Quốc nhìn sang hướng cáp treo Hòn Thơm)</span></p></div><h2 id=\\\"ftoc-heading-14\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Qua trình đàm phàn và chốt giá vận chuyển thiết bị cáp treo như thế nào, có phức tạp không?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Lô hàng này đã được chốt không khoãng thời gian hơi lâu, chắc có thể là do phải lựa chọn ở rất nhiều đơn vị vận chuyển cùng đấu thầu, nên dẫn đến thời gian hơi lâu.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Còn nói về khó hay phức tạp ở báo giá thì không có gì khó, có thể là Khách hàng trước khi chọn một đơn vị vận tải nào đó thì cũng đã tìm hiểu đối tác mà họ sắp hợp tác sẽ làm được những gì cho họ.</span></p><div id=\\\"attachment_799\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-799\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-799 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-7.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-7.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-7-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-799\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là xà lan, tàu chở thiết bị cáp treo cặp bếp, chuẩn bị đưa cẩu đến để di chuyển hàng hóa lên công trình)</span></p></div><h2 id=\\\"ftoc-heading-15\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Con Rùa Biển cần bao nhiêu thời gian để chốt giá vận chuyển thiết bị cáp treo Hòn Thơm cho một dự án lớn?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Sau khi nhận được thông tin yêu cầu báo giá từ Khách hàng thì Con Rùa Biển đã cử chuyên viên phụ trách đi khảo sát vị trí, tuyến đường, và thời gian cần vận chuyển lô hàng. Về lại công ty đã cùng Ban lạnh đạo công ty đưa ra các phương án vận chuyển, dự phòng rủi ro phát sinh, cân đối báo giá của đối thủ cạnh tranh và đưa ra báo giá cuối cùng trong vòng 1 ngày kể từ lúc đi khảo sát dự án vận chuyển thiết bị cáp treo Hòn Thơm</span></p><div id=\\\"attachment_798\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-798\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-798 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-6.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"1365\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-6.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-6-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-798\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là tàu, xà lan được chụp khi gần đến nơi cặp bến tại Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-16\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Con Rùa Biển đã áp dụng phương án vận chuyển thiết bị cáp treo nào để tối đa hóa chi phí cho khách hàng?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Có 2 phương án chính mà Con Rùa Biển đã áp dụng:</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đợt nào hàng thiết bị cáp treo nhiều thì sẽ áp dụng vận chuyển bằng tàu biển (hay còn gọi là xà lan đi biển) để vận chuyển toàn bộ một lần dứt điểm đợt hàng đó. Xà làn (tàu biển) được áp dụng thường xuyên là loại 1.500 tấn đến loại xà lan 3.000 tấn là được sử dụng thường xuyên nhất cho dự án vận chuyển thiết bị lần này.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nếu mỗi lần hàng nhập thiết bị về chỉ có vài container thì sẽ được dùng xe đầu kéo container chuyên dụng để chở container từ HCM đi thẳng ra Đảo Phú Quốc luôn, vì Con Rùa Biển có phà đưa xe đầu kéo qua đảo Phú Quốc hằng ngày tại Hà Tiên, Kiên Giang.</span></p><div id=\\\"attachment_805\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-805\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-805 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-13.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-13.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-13-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-805\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; trong ảnh là bãi tập kết thiết bị xây dựng cáp treo Hòn Thơm)</span></p></div><h2 id=\\\"ftoc-heading-17\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dự án vận chuyển thiết bị cáp treo Hòn Thơm có những khó khăn gì trong quá trình vận chuyển?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đã làm hàng dự án trong lĩnh vực vận chuyển thì việc gặp phải khó khăn đó là điều chắc chắn có thể xảy ra, nhưng để hạn chế và khắc phục những vấn đề khó khăn đó bằng cách nào, hướng giải quyết như thế nào đó là điều mà bất kỳ một đơn vị vận tải nào cũng phải dự đoán được trước.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khi bắt đầu báo giá cho một dự án nào đó cần phải dự đoán trước những khó khăn sẽ gặp phải là gì? Và phải có kế hoạch dự phòng trước khi báo giá luôn. Thì khi nếu có khó khăn đó phát sinh thì chắc chắn đơn vị vận tải đó sẽ xử lý dự án đó trong tầm tay của họ.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ở dự án này Chúng tôi đã gặp phải nhiều vấn đề về thời tiết, gặp mưa bão rất nhiều lần đã làm chậm trễ tiến độ giao hàng cho nhà thầu thi công. Nhưng những vấn đề đi biển này đã được cảnh báo ngay từ đầu trong hợp đồng vận tải, nhưng Chúng tôi cũng phần nào xử lý việc chậm trễ một cách nhẹ nhàng và êm đẹp cho đôi bên.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khó khăn thứ 2 là xe vào cổng dự án bị kẹt đường, vì một dự án sẽ có 1 cổng chính để cho xe vật tư công trình ra vào để dễ kiểm soát, điều đó với số lượng lớn thiết bị ra vào cổng chậm đã làm phát sinh thêm thời gian cho việc giao hàng.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Và cũng có lần phải chạy xe đi vào công trình với một quãng đường dài gấp đôi dự kiến ban đầu, do thời tiết khắt nghiệt sóng biển cao thất thường, Chúng tôi phải thay đổi Cảng biển để dễ lên xuống hàng, Phải chuyển thiết bị từ Cảng an Thới về lại Cảng Vịnh Đầm để lên hàng, cẩu hàng lên xe chạy từ Cảng Vịnh Đầm về Nhà Ga Đi An Thới thay vị Tàu biển cặp Cảng An Thới sẽ kéo hàng về An Thới sẽ gần hơn rất nhiều.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ngoài ra còn có rất nhiều những phát sinh tại dự án, nhưng điều đó không làm cho Con Rùa Biển phải thỏa thuận tăng giá với khách hàng bao giờ, mà tất cả khó khăn đó đã được ban lãnh đạo công ty lường trước rủi ro phát sinh, nên ngay từ đầu báo giá đã được tính toán rất kỹ trong báo giá.</span></p><div id=\\\"attachment_803\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-803\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-803 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-11.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-11.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-11-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-803\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh đang cẩu thiết bị từ dưới tàu, xà lan lên bờ để chuyển về bãi tập kết của Nhà Ga Đi An Thới)</span></p></div><h2 id=\\\"ftoc-heading-18\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hình ảnh chi tiết của dự án vận chuyển thiết bị cáp treo Hòn Thơm, Phú Quốc</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Sau đây là một số hình ảnh vận chuyển hàng hóa Cáp Treo của Tập Đoàn Sun Group từ Cảng Vict HCM đi ra Đảo Phú Quốc kết hợp đường bộ và đường biển mà Chúng tôi vừa mới thực hiện gần đây:</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\">&nbsp;</p><div id=\\\"attachment_804\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-804\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-804 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-12.jpg\\\" alt=\\\"(Ảnh dự án: vận chuyển thiết bị cáp treo hòn thơm phú quốc kiên giang)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-12.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-12-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-804\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự Án vận chuyển thiết bị cáp treo đi Hòn Thơm; hình ảnh cẩu xe điện từ dưới xà lan, tàu biển lên bờ để chuyển về bãi thiết bị tại An Thới, Phú Quốc)</span></p></div><div id=\\\"attachment_802\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spac