yle=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 0, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">www.conruabien.vn</em></strong></a></span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\"><span>&nbsp;</span>– Chành xe Phú Quốc –<span>&nbsp;</span></em></strong><span style=\\\"box-sizing: border-box; color: rgb(255, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">0945 000 006</em></strong></span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">)</em></strong></span></p>\"','2024-06-18 11:40:03','/du-an-da-van-chuyen/du-an-van-chuyen-ket-cau-thep-atad-ra-dao-phu-quoc-xay-dung-cong-trinh-cua-masan-phu-quoc',NULL,0,3,NULL,NULL,NULL);
INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (239,14,'Dự án Vận chuyển Kết cấu thép ATAD ra Sân Bay Quốc Tế Phú Quốc','Dự án vận tải sắt thép ATAD ra Sân Bay Quốc Tế Phú Quốc Từ ngày 12/12/2012, Vietnam Airlines sẽ khai thác đường bay Hà Nội – Phú Quốc với tần suất 5 chuyến/tuần sử dụng máy bay Airbus A321, đồng thời sử dụng loại máy bay .…','https://conruabien.vn/wp-content/uploads/2021/05/%E1%BA%A2nh-b%C3%ACa-D%E1%BB%B1-%C3%81n-v%E1%BA%ADn-chuy%E1%BB%83n-k%E1%BA%BFt-c%E1%BA%A5u-th%C3%A9p-ra-c%C3%B4ng-tr%C3%ACnh-S%C3%A2n-Bay-Ph%C3%BA-Qu%E1%BB%91c-c%E1%BB%A7a-ATAD-1.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dự án vận tải sắt thép ATAD ra Sân Bay Quốc Tế Phú Quốc</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Từ ngày 12/12/2012, Vietnam Airlines sẽ khai thác đường bay Hà Nội – Phú Quốc với tần suất 5 chuyến/tuần sử dụng máy bay Airbus A321, đồng thời sử dụng loại máy bay này trong một số chuyến bay giữa TP. Hồ Chí Minh – Phú Quốc.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Và cho đến hôm nay thì có rất nhiều chuyến bay từ tất cả các nơi<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Sân Bay Quốc Tế Phú Quốc</strong>, lúc cao điểm hơn 100 chuyến bay / ngày.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Chính vì điều đó, để đáp ứng như cầu vận hành sân bay một cách tốt nhất nên Sân Bay Quốc Tế Phú Quốc đã được mở rộng thêm rất nhiều hạng mục quan trọng, trong đó có hạng mục nhà ga, đường dẫn cho xe ô tô lên tầng trên … và nhiều hạng mục dịch vụ khác trong sân bay.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Và cũng từ đó Con Rùa Biển đã thực hiện nhiều<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"1255\\\" href=\\\"https://conruabien.vn/du-an-da-van-chuyen/du-an-van-chuyen-ket-cau-thep-atad-ra-san-bay-quoc-te-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">dự án vận chuyển trang thiết bị vật tư và kết cấu thép xây dựng công trình cho Sân Bay Quốc Tế Phú Quốc.</strong></a></span></span></p><div id=\\\"attachment_1270\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-1270\\\" decoding=\\\"async\\\" class=\\\"wp-image-1270 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%81n-v%E1%BA%ADn-chuy%E1%BB%83n-k%E1%BA%BFt-c%E1%BA%A5u-th%C3%A9p-ra-c%C3%B4ng-tr%C3%ACnh-S%C3%A2n-Bay-Ph%C3%BA-Qu%E1%BB%91c-c%E1%BB%A7a-ATAD-13.jpg\\\" alt=\\\"(Ảnh Dự Án Vận chuyển Kết cấu thép ATAD từ Long An đi Sân Bay Quốc Tế Phú Quốc)\\\" width=\\\"1024\\\" height=\\\"683\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-Án-vận-chuyển-kết-cấu-thép-ra-công-trình-Sân-Bay-Phú-Quốc-của-ATAD-13.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-Án-vận-chuyển-kết-cấu-thép-ra-công-trình-Sân-Bay-Phú-Quốc-của-ATAD-13-768x512.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1270\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">(Ảnh: Dự án vận chuyển Kết cấu sắt thép của ATAD từ Long An đi ra Sân Bay Quốc tế Phú Quốc; trong ảnh là cảnh xe cẩu kato 45 tấn đang cẩu kết cấu thep từ xe đầu kéo chở hàng từ cảng về bãi tập kết tại Sân Bay Phú Quốc)</span></p></div><h2 id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligature