INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (243,14,'Vận chuyển Dàn Máy Khoan Đóng Cọc Thủy Lực','Loại xe nào có thể Vận chuyển Dàn Máy Khoan Đóng Cọc Thủy Lực được một cách tốt nhất? Ở Việt Nam nói chung thì có rất nhiều xe chở được loại mặt hàng này. Nhưng cũng nhìn chung thì chỉ có dòng xe đầu kéo là thông dụng nhất. Ngoài ra còn có thêm…','https://conruabien.vn/wp-content/uploads/2021/07/anh-bia.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Loại xe nào có thể<span>&nbsp;</span></strong><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển</strong><span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dàn Máy Khoan Đóng Cọc Thủy Lực được một cách tốt nhất?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-s