INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (246,5,'Hướng dẫn Vận chuyển hàng Nội thất | An toàn – Chuyên nghiệp','Tại sao vận chuyển nội thất rất thường xuyên hư hỏng xảy ra? Đây là một vấn đề được nhiều khách hàng quan tâm đến, nên Con Rùa Biển hôm sẽ viết một bài phân tích về các nguyên nhân hư hỏng nội thất, cách khắc phục và chia sẽ kinh nghiệm','https://conruabien.vn/wp-content/uploads/2021/08/Du-an-Van-chuyen-Gach-men-24.jpg','\"<h2 data-header=\\\"0\\\" id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255); text-align: justify;\\\">Tại<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">sao<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">nội thất</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>rất thường xuyên hư hỏng xảy ra?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-