INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (251,5,'Kinh nghiệm đi thuê kho bãi','Kinh nghiệm đi thuê kho bãi cần lưu ý những điều sau đây: 1. Vị trí thuê – Kinh nghiệm đi thuê kho bãi Kinh nghiệm đi thuê kho bãi : là địa điểm bạn muốn đặt để làm nơi lưu giữ , bảo quản hàng hóa. Do đó phải đáp ứng các tiêu chuẩn…','https://conruabien.vn/wp-content/uploads/2021/03/VAN-CHUYEN-HANG-HOA-NHO-LE-TU-HCM-DI-PHU-QUOC-GHEP-XE-TAI-14.jpg','\"<h2 data-header=\\\"0\\\" id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\">Kinh nghiệm đi thuê kho bãi cần lưu ý những điều sau đây:</h2><h2 data-header=\\\"1\\\" id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">1. Vị trí thuê</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>–<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a data-mil=\\\"58\\\" href=\\\"https://conruabien.vn/goc-chia-se-kinh-nghiem/kinh-nghiem-di-thue-kho-bai/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Kinh nghiệm đi thuê kho bãi</a></span><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>: là địa điểm bạn muốn đặt để làm nơi lưu giữ , bảo quản hàng hóa. Do đó phải đáp ứng các tiêu chuẩn sau:</p><div id=\\\"attachment_1419\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1419\\\" decoding=\\\"async\\\" class=\\\"wp-image-1419 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/h%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-%C4%91%C3%B3ng-g%C3%B3i-v%C3%A0-v%E1%BA%ADn-chuy%E1%BB%83n-n%E1%BB%99i-th%E1%BA%A5t-%C4%91i-%C4%91%C6%B0%E1%BB%9Dng-b%E1%BB%99-b%E1%BA%B1ng-xe-t%E1%BA%A3i-6.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/hướng-dẫn-chia-sẽ-kinh-nghiệm-đóng-gói-và-vận-chuyển-nội-thất-đi-đường-bộ-bằng-xe-tải-6.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/hướng-dẫn-chia-sẽ-kinh-nghiệm-đóng-gói-và-vận-chuyển-nội-thất-đi-đường-bộ-bằng-xe-tải-6-768x576.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1419\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Hướng dẫn và chia sẽ kinh nghiệm đóng gói Nội thất khi vận chuyển đường bộ bằng xe tải; Trong ảnh là cảnh hàng nhẹ mây tre lái, nên đã đóng gói kỹ, carton, màng co và bỏ vào bao, do hàng rất nhẹ nên khi vận chuyển sẽ được xếp bên trên các loại hàng hóa khác để được an toàn không bị cấn hay va chạm với hàng khác khi vận chuyển)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Là nơi trung chuyển hàng hóa, kho phải thuận tiện cho xe lưu thông nhằm đáp ứng kịp thời việc phân phối hàng hóa từ nhà cung cấp đến bạn hoặc từ bạn đến người dùng. Giúp bạn giao hàng nhanh hơn, chiếm lĩnh vùng thị trường tốt hơn. Do đó, bạn cần tìm kho tại những khu vực có vị trí giao thông thuận tiện hoặc có thể tìm đến người có<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm đi thuê kho bãi</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>để được tư vấn tốt hơn.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Kho có nền cao ráo, không bị ngập, đặc biệt bạn cần lưu ý trong khu vực bạn định thuê có hay xảy ra tình trạng ngập, điều này có lẽ người thuê thường không lường trước được tình huống hoặc có thể tìm đến người có<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm đi thuê kho bãi</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>để được tư vấn tốt hơn.</p><div id=\\\"attachment_1344\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1344\\\" decoding=\\\"async\\\" class=\\\"wp-image-1344 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-28.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"2400\\\" height=\\\"1657\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-28.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-28-768x530.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1344\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe Phà chuyên dụng chở Container đi trên biển để đến đảo Hòn Thơm, cả xe đầu kéo và container cùng lên phà để qua đảo còn nguyên seal)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">VD: khu vực bạn định thuê có vị trí nằm trong vùng ngập hoặc bị cô lập ngập mỗi khi trời mưa thì thật là tai họa. Khi đó, bạn sẽ ít nhiều bị ảnh hưởng tiến độ hoặc hàng hóa phân phối sẽ chậm. Khu vực đó chắc chắn có độ ẩm cao và sẽ không thích hợp chứa hàng thực phẩm. Dễ bị mối mọt, chuột.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Kho tập trung hay kho độc lập, riêng rẽ. Tôi lưu ý bạn điểm này đối với các doanh nghiệp nhỏ, hoặc mới khởi nghiệp. Vì nếu kho nằm riêng rẽ không tập trung, khi bạn có nhu cầu vận chuyển hoặc bốc xếp. Bạn sẽ trở nên khó khăn trong việc tìm nhân công bốc xếp, xếp dỡ hàng hóa hoặc người vận chuyển hàng hóa cho bạn. Bạn sẽ điều phối xe ở nơi khác và giá thành sẽ cao hơn. Do đó, bạn cần biết sẽ lựa chọn sao cho phù hợp rồi chứ? hoặc có thể tìm đến người có<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm đi thuê kho bãi</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>để được tư vấn tốt hơn.</p><h2 data-header=\\\"2\\\" id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">2. Diện tích &amp; hình thức thuê</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>–<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong>: Hiện nay, trên thị trường cho thuê kho bãi khá nhiều, và cũng rất đa dạng hình thức lựa chọn để thuê như: thuê theo mét, thuê theo đầu tấn, thuê theo dạng khoán, ….</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">Do đó, người thuê cần xác định lượng hàng tồn trữ, quy cách sắp xếp có thể chất cao bao nhiêu lớp, bao nhiêu dãy, bao nhiêu mã hàng, để có thể xác định được diện tích cần thuê. Nếu mã hàng cần phân loại số lô, số lot…sẽ phải mất nhiều diện tích lối đi để lấy hàng. Thông thường phần lối đi chiếm khoảng 10% trong diện tích chất hàng hóa.</p><div id=\\\"attachment_1330\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-1330\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1330 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-15.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"1920\\\" height=\\\"1080\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-15.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-15-768x432.jpg 768w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1330\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe đầu kéo chở container nguyên seal vừa mới từ Phà leo lên cảng Hòn Thơm, các xe đầu kéo bắt đầu leo con dốc đầu tiên trên đảo Hòn Thơm)</p></div><h2 data-header=\\\"3\\\" id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">3. Giá thuê</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>–<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong>:</h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi:<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span></strong>Giá thuê thuê tùy theo khu vực, tình trạng kho, cơ sở đầu tư vật chất PCCC, môi trường, có cầu xe nâng, palang,… mà có thuê khác nhau. Có những kho có các dịch vụ quản lý hàng hóa đi kèm sẽ có giá cao hơn, nhưng người thuê sẽ giảm bớt được chi phí quản lý nhân sự, rủi ro hàng hóa,…</p><div id=\\\"attachment_1323\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1323\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1323 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-5-container-thi%E1%BA%BFt-b%E1%BB%8B-%C4%91i-H%C3%B2n-Th%C6%A1m-8.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-8.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-5-container-thiết-bị-đi-Hòn-Thơm-8-768x432.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1323\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển 5 Container thiết bị cho Công trình Sun World Hòn Thơm; Trong ảnh là cảnh xe tải kết hợp với xe nâng máy dầu để đưa hàng thiết bị vào trong kho lưu trữ tại đảo Hòn Thơm)</p></div><h2 data-header=\\\"4\\\" id=\\\"ftoc-heading-5\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">4. Thời gian thuê</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>–<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong>: Đa phần khi bạn đi thuê, bạn đều mong muốn được sự ổn định dài lâu. Tuy nhiên, bạn cần xem xét các khoản nội dung hợp đồng thuê, sự đầu tư cơ sở hạ tầng của bạn mà quyết định ký kết thời gian dài hạn.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">Thông thường bạn nên ký thời hạn thuê là 01 năm. Sau khi hết hạn hợp đồng trên, cân nhắc lại nhu cầu mà điều chỉnh gia hạn thêm bằng phụ lục. Nếu bạn xác định lâu dài, bạn ký nhiều năm thì cần xem xét biên độ tăng giá hàng năm nhé, biên độ thường dao động từ 10% – 20%.</p><div id=\\\"attachment_1241\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-1241\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-1241\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-Thi%E1%BA%BFt-b%E1%BB%8B-v%E1%BA%ADt-t%C6%B0-C%C3%B4ng-Tr%C3%ACnh-Nh%C3%A0-M%C3%A1y-Nhi%E1%BB%87t-%C4%90i%E1%BB%87n-Nam-S%C3%B4ng-H%E1%BA%ADu-H%E1%BA%ADu-Giang-24.jpg\\\" alt=\\\"Dự án vận chuyển Thiết bị vật tư Công Trình Nhà Máy Nhiệt Điện Nam Sông Hậu Hậu Giang 24\\\" width=\\\"1024\\\" height=\\\"683\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-Thiết-bị-vật-tư-Công-Trình-Nhà-Máy-Nhiệt-Điện-Nam-Sông-Hậu-Hậu-Giang-24.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-Thiết-bị-vật-tư-Công-Trình-Nhà-Máy-Nhiệt-Điện-Nam-Sông-Hậu-Hậu-Giang-24-768x512.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1241\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển thiết bị vật tư công trình Nhà Máy Nhiệt Điện Nam Sông Hậu – Hậu Giang; Ảnh được chụp lại cảnh xe cẩu kato loại lớn (kato loại 45 tấn, loại 75 tấn, loại 125 tấn có đủ) để di chuyển trang thiết bị vật tư tại công trình)</p></div><h2 data-header=\\\"5\\\" id=\\\"ftoc-heading-6\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">5. Tiền đặt cọc thuê kho</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>–<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm đi thuê kho bãi</strong>: Bạn cũng quan tâm với số tiền đặt cọc thuê kho? Khi tiến hành hợp đồng sẽ có một khoản tiền giao kết giữ cọc giữa 02 bên dao động khoảng 03 tháng trở lại, đỡ chiếm dụng vốn nhiều của bạn. Và hình thức thanh toán cuối tháng, nếu thanh toán đàu tháng thì tiền cọc được áp dụng là 02 tháng. Số tiền nhằm đảm bảo thanh toán đúng hạn của bạn, trong trường hợp mất khả năng thanh toán sẽ được cấn trừ vào tiền thuê kho, chi phí điện nước.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">Lãi suất thanh toán chậm sẽ là 2% x số ngày chậm x số tiền cần thanh toán.</p><div id=\\\"attachment_1158\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-1158\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1158 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-k%E1%BA%BFt-c%E1%BA%A5u-th%C3%A9p-ATAD-ra-%C4%91%E1%BA%A3o-Ph%C3%BA-Qu%E1%BB%91c-x%C3%A2y-d%E1%BB%B1ng-c%C3%B4ng-tr%C3%ACnh-c%E1%BB%A7a-MASAN-PQ-20.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"1024\\\" height=\\\"683\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-kết-cấu-thép-ATAD-ra-đảo-Phú-Quốc-xây-dựng-công-trình-của-MASAN-PQ-20.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-kết-cấu-thép-ATAD-ra-đảo-Phú-Quốc-xây-dựng-công-trình-của-MASAN-PQ-20-768x512.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1158\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển kết cấu thép của ATAD ra đảo Phú Quốc để xây dựng công trình cho nhà máy sản xuất nước mấm MASAN Phú Quốc. Trong ảnh là cảnh: xe cẩu 4 chân 20 tấn đang cẩu kết cẩu thép từ xe tải 20 tấn bỏ xuống tàu biển để vận chuyển qua Đảo Phú Quốc bằng đường biển)</p></div><h2 data-header=\\\"6\\\" id=\\\"ftoc-heading-7\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">6. Dịch vụ cung cấp – Kinh nghiệm đi thuê kho bãi</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">Các dịch vụ cung cấp tại kho cho thuê có đầy đủ không, đã gồm các dịch vụ cơ bản như sau:</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Dịch vụ cung cấp điện</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Dịch vụ nước sinh hoạt</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Dịch vụ bốc xếp xe nâng- nhân công</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Dịch vụ vận chuyển hàng hóa.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Dịch vụ quản lý hàng hóa.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– …..</p><div id=\\\"attachment_1127\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-1127\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1127 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%81n-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-%C4%91i%E1%BB%87n-t%E1%BB%AB-B%E1%BA%AFc-v%C3%A0o-Nam-v%C3%A0-%C4%91i-kh%E1%BA%AFp-c%C3%A1c-t%E1%BB%89nh-mi%E1%BB%81n-t%C3%A2y-30.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"1024\\\" height=\\\"683\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-Án-vận-chuyển-cáp-điện-từ-Bắc-vào-Nam-và-đi-khắp-các-tỉnh-miền-tây-30.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-Án-vận-chuyển-cáp-điện-từ-Bắc-vào-Nam-và-đi-khắp-các-tỉnh-miền-tây-30-768x512.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1127\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển Cáp Điện từ Bắc vào Nam và phân phối cho các Tỉnh, Thành Phố ở Miền Tây; hình ảnh cho thấy: xà lan 2.000 tấn đang được xe cẩu kato 45 tấn, cẩu hàng từ xà lan lên xe đầu kéo để trung chuyển một lượng nhỏ cáp điện đi đến một trạm cáp điện gần đó, cách bên khoãng 5km, tại đây là Bên Sông thuộc địa phận Tỉnh Sóc Trăng)</p></div><h2 data-header=\\\"7\\\" id=\\\"ftoc-heading-8\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">7. Những điều khoản cần có trong hợp đồng:</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Đảm bảo an ninh, an toàn, ổn định giá trong suốt thời gian thuê.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Trong trường hợp thanh lý hợp đồng trước thời hạn, báo trước bằng văn bảng 30 ngày.</p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">– Trong quá trình thực hiện Hợp đồng, nếu có sửa đổi hoặc bổ sung thì các bên sẽ tiến hành lập phụ lục hợp đồng, mẫu giấy ủy quyền. Phụ lục hợp đồng, mẫu giấy ủy quyền là một phần không tách rời của hợp đồng này. Khi có sự thay đổi thông tin về chủ thể ủy quyền hoặc nhận ủy quyền khách hàng có nghĩa vụ thông báo về việc thay đổi.</p><div id=\\\"attachment_1032\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1034px;\\\"><img aria-describedby=\\\"caption-attachment-1032\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1032 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-c%E1%BB%99t-%C4%91%C3%A8n-S%E1%BA%AFt-Th%C3%A9p-t%E1%BB%AB-%C4%90%E1%BB%93ng-Nai-%C4%91i-Ph%C3%BA-Qu%E1%BB%91c-5.jpg\\\" alt=\\\"Kinh nghiệm đi thuê kho bãi\\\" width=\\\"1024\\\" height=\\\"576\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-cột-đèn-Sắt-Thép-từ-Đồng-Nai-đi-Phú-Quốc-5.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/05/Dự-án-vận-chuyển-cột-đèn-Sắt-Thép-từ-Đồng-Nai-đi-Phú-Quốc-5-768x432.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1032\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Dự án vận chuyển cột đèn sắt thép từ Đồng Nai đi Phú Quốc, được cty Con Rùa Biển vận chuyển kết hợp đa phương thức bằng đường bộ, đường biển, với các loại phương tiện chuyên dụng từ Đầu kéo container mui bạc, cho đến xe tải và kết hợp cả tàu biển để đưa hàng đến chân công trình)</p></div><h2 data-header=\\\"8\\\" id=\\\"ftoc-heading-9\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">8. Ký kết hợp đồng:</strong></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255);\\\">Hai bên ký tên đóng dấu, kèm theo giấy phép ĐKKD ngành nghề mỗi công ty.</p><h2 data-header=\\\"9\\\" id=\\\"ftoc-heading-10\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><em style=\\\"box-sizing: border-box;\\\">Bên dưới đây là một quy trình từ lúc tiếp nhận thông tin yêu cầu vận chuyển của Quý khách hàng cho đến khi hoàn thành xong việc giao nhận hàng hóa và thu tiền:</em></span></h2><ol style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Tiếp nhận thông tin yêu cầu vận chuyển hàng hóa từ khách hàng:</strong></li></ol><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Nhận thông tin yêu cầu<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>của Quý khách hàng về việc vận chuyển hàng hóa đi các tỉnh, TP lớn nên<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Con Rùa Biển</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>đã cung cấp các dịch vụ vận tải:<ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 0px;\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ vận chuyển hàng hóa đường bộ Bắc Nam</strong></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe tải đi Phú Quốc</strong></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe đầu kéo container đi Phú Quốc</strong></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ cho thuê xe cẩu tại Phú Quốc</strong></li><li style=\\\"box-sizing: border-box;\\\"><a href=\\\"http://vantainoidia.vn/dich-vu/chanh-xe-van-chuyen-hang-hoa-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Chành xe Phú Quốc</strong></a></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Gửi hàng nhỏ lẻ đi Phú Quốc</strong></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển hàng hóa đi Phú Quốc ..</strong>. và một số dịch vụ hỗ trợ việc vận chuyển mở rộng:<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">nhận đóng kiện gỗ hàng hóa, nhận bốc xếp hàng hóa, cho thuê xe nâng máy, cho thuê xe nâng tay</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>…</li></ul></li><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Con Rùa Biển</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>sẽ&nbsp;cử Chuyên viên phụ trách đến tận nơi kiểm tra “Mặt hàng” cần vận chuyển</li><li style=\\\"box-sizing: border-box;\\\">Xác định trọng lượng hàng hóa, kích thước hàng hóa, địa chỉ giao nhận hàng hóa, thời gian yêu cầu vận chuyển hàng hóa</li><li style=\\\"box-sizing: border-box;\\\">Sau khi gặp trực tiếp và trao đổi, Con Rùa Biển sẽ tư vấn cho Quý khách hàng cách thức vận chuyển hàng hóa (hoặc<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><a data-mil=\\\"58\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/chanh-xe-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">dịch vụ vận chuyển hàng hóa đi Phú Quốc</strong></a>) sao cho đảm bảo an toàn, cũng như là tư vấn cách đóng gói hàng hóa khi vận chuyển đảm bảo an toàn không bị hư hỏng trong quá trình vận chuyển đường dài.</li></ul><ol start=\\\"2\\\" style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Báo giá vận chuyển hàng hóa:</strong></li></ol><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Dựa vào thông tin hàng hóa đã thực tế kiểm tra được để báo giá gồm có:</li></ul><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box; list-style-type: none;\\\"><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 0px;\\\"><li style=\\\"box-sizing: border-box;\\\">Trọng lượng / kiện</li><li style=\\\"box-sizing: border-box;\\\">Kích thước / kiện</li><li style=\\\"box-sizing: border-box;\\\">Tổng số kiện đã thực tế kiểm tra,</li></ul></li></ul><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Sau đó đưa ra mức giá phù hợp để vận chuyển toàn bộ lô hàng theo yêu cầu mà bên gửi hàng đưa ra.</li><li style=\\\"box-sizing: border-box;\\\">Xác nhận báo giá bằng văn bản (<strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">báo giá vận chuyển hàng hóa</strong>).</li><li style=\\\"box-sizing: border-box;\\\">Lập phiếu yêu cầu vận chuyển hàng hóa.</li><li style=\\\"box-sizing: border-box;\\\">Lên hợp đồng vận chuyển hàng hóa (hoặc<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">hợp đồng vận chuyển hàng hóa đi Phú Quốc</strong>), cũng như là cam kết ngày gửi hàng và giao hàng theo đúng tiến độ thực hiện.</li></ul><ol start=\\\"3\\\" style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Điều xe để lấy hàng:</strong></li></ol><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Sắp xếp xe tải lớn (hoặc các loại xe phù hợp với nhu cầu thực tế) để lấy hàng tận nơi theo yêu cầu<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>đã được thỏa thuận</li><li style=\\\"box-sizing: border-box;\\\">Đối với hàng có trọng lượng trên 100kg/kiện thì sẽ được điều xe cẩu (tải trọng cẩu phù hợp) để đưa hàng lên xe tải lớn tại địa điểm gửi hàng (nếu trong hợp đồng đã có thỏa thuận bao bốc xếp)</li><li style=\\\"box-sizing: border-box;\\\">Ký biên bản giao nhận hàng hoá tại nơi nhận, xác nhận và kiểm tra thực tế việc giao nhận hàng hóa tại nơi gửi.</li></ul><ol start=\\\"4\\\" style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Giao hàng tận nơi:</strong></li></ol><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Khi xe đi hàng đường dài sẽ alo cho người nhận trước 1 ngày, nếu đi gần thì alo cho người nhận trước khi giao hàng 2 giờ, để 2 bên cùng phối hợp giao nhận cho hợp lý.</li><li style=\\\"box-sizing: border-box;\\\">Cho xe cẩu hàng từ xe tải lớn đưa hàng xuống đất nếu đó là hàng nặng và có thỏa thuận bao cẩu hạ hàng.</li><li style=\\\"box-sizing: border-box;\\\">Ký<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">biên bản giao nhận vận chuyển hàng hoá</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>sau khi hoàn tất việc giao hàng.</li><li style=\\\"box-sizing: border-box;\\\">Đem về biên bản giao nhận hàng hoá có đầy đủ chữ ký của người nhận về lại công ty và gửi 1 bản chính về lại cho người gửi nếu có yêu cầu.</li></ul><ol start=\\\"5\\\" style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kết thúc hợp đồng theo lô và thanh toán tiền cước vận chuyển.</strong></li></ol><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; background-color: rgb(255, 255, 255);\\\"><li style=\\\"box-sizing: border-box;\\\">Chuyển hồ sơ hợp đồng qua phòng kế toán làm bảng kê cước phí vận chuyển hàng hóa</li><li style=\\\"box-sizing: border-box;\\\">Xuất hóa đơn</li><li style=\\\"box-sizing: border-box;\\\">Thu tiền</li><li style=\\\"box-sizing: border-box;\\\">Kết thúc một đơn hàng</li></ul><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: right;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">(Nguồn:<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span></em></strong><a href=\\\"https://conruabien.vn/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">www.conruabien.vn</em></strong></a><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>– Chành xe Phú Quốc)</em></strong></p>\"','2024-04-17 04:07:36','/goc-chia-se-kinh-nghiem/kinh-nghiem-di-thue-kho-bai',NULL,0,1,NULL,NULL,NULL);
INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (252,5,'Hướng dẫn và Chia sẻ kinh nghiệm vận chuyển hàng hóa Cáp Điện bằng xe tải đường bộ Bắc Nam','Kinh nghiệm vận chuyển cáp điện từ đâu? Ngoài việc vận chuyển hàng hóa cáp điện (kinh nghiệm vận chuyển cáp điện) là đường bộ bằng xe tải thùng 15 tấn và 20 tấn, hoặc xe đầu kéo container thì Chành xe Phú Quốc – Con Rùa Biển còn kết hợp cả đường...','https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%81n-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-%C4%91i%E1%BB%87n-t%E1%BB%AB-B%E1%BA%AFc-v%C3%A0o-Nam-v%C3%A0-%C4%91i-kh%E1%BA%AFp-c%C3%A1c-t%E1%BB%89nh-mi%E1%BB%81n-t%C3%A2y-28.jpg','\"<div id=\\\"attachment_1435\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-1435\\\" decoding=\\\"async\\\" class=\\\"wp-image-1435 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-13.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"1920\\\" height=\\\"1586\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-13.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-13-768x634.jpg 768w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1435\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh hàng hóa cáp điện vận chuyển đã đóng gói và ràng buộc chưa được cẩn thận, dẫn đến có một số cuộn cáp đã bị xô lệch sang một bên, điều này rất nguy hiểm nếu xe chạy đường dài, cần phải ràng buộc bằng dây cảo và cố định thêm bằng gỗ lót vào các cuộn cáp để giữ cuộn cáp cố định khi vận chuyển)</p></div><h2 data-header=\\\"0\\\" id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm vận chuyển cáp điện từ đâu?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ngoài việc<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>(<strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong>) là đường bộ bằng xe tải thùng 15 tấn và 20 tấn, hoặc xe đầu kéo container thì<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><a data-mil=\\\"55\\\" href=\\\"https://conruabien.vn/dich-vu-chinh/chanh-xe-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Chành xe Phú Quốc – Con Rùa Biển</strong></a><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>còn kết hợp cả<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">đường thủy nội địa</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>để vận chuyển hàng hóa cáp điện đến tận chân công trình ở các tỉnh, thành phố của miền tây.</span></p><div id=\\\"attachment_1432\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1432\\\" decoding=\\\"async\\\" class=\\\"wp-image-1432 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-10.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"3200\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-10.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-10-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1432\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh mà cuộn cáp điện đã bị hư một phần gỗ , cho thấy lỗi ở đây là do đóng gỗ chèn lót và nhỏ và mỏng, nên đã bị cuộn cáp điện lăn qua trong quá trình vẫn chuyển, dẫn đến cuộn cáp điện đã bị hư một vài miếng gỗ, tuy nhiên không ảnh hướng đến cáp điện bên trong, đây cũng là một bài học kinh nghiệm rất quan trọng cần lưu ý khi vận chuyển cáp điện loại lớn, cần phải đóng gỗ chèn lót nhiều, gỗ bự và chắc chắn, đóng gỗ chèn lót phải cao để tránh cuộn cáp điện lăn qua được.)</p></div><h2 data-header=\\\"1\\\" id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm vận chuyển cáp điện cần bao nhiêu năm?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Để<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển được cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>loại lớn cần phải chú ý rất nhiều kỹ năng khó và<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><a data-mil=\\\"55\\\" href=\\\"https://conruabien.vn/goc-chia-se-kinh-nghiem/chia-se-kinh-nghiem-van-chuyen-cap-dien/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong></a><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>thực tế của người điều hành vận tải hàng hóa đường dài Bắc Nam. Vì cáp điện là một mặt hàng nặng, lớn và tròn, rất dễ lăn khi xe chạy tốc độ cao, sẽ rất nguy hiểm khi tham gia giao thông nếu không được vận chuyển đúng cách và kỹ năng chằng buộc khi vận chuyển mặt hàng này.</span></p><div id=\\\"attachment_1431\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1431\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1431 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-9.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-9.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-9-768x576.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1431\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh mà cuộn cáp điện đã bị hư một phần gỗ , cho thấy lỗi ở đây là do đóng gỗ chèn lót và nhỏ và mỏng, nên đã bị cuộn cáp điện lăn qua trong quá trình vẫn chuyển, dẫn đến cuộn cáp điện đã bị hư một vài miếng gỗ, tuy nhiên không ảnh hướng đến cáp điện bên trong, đây cũng là một bài học kinh nghiệm rất quan trọng cần lưu ý khi vận chuyển cáp điện loại lớn, cần phải đóng gỗ chèn lót nhiều, gỗ bự và chắc chắn, đóng gỗ chèn lót phải cao để tránh cuộn cáp điện lăn qua được.)</p></div><h2 data-header=\\\"2\\\" id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm vận chuyển cáp điện cần lưu ý điều gì?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Trong quá trình<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>(<strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện)<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span></strong>nếu không được ràng buộc cẩn thận sẽ dẫn đến cáp điện lăn xuống đường khi giao gia giao thông, hoặc là các cuộn cáp điện sẽ tự xô vào nhau nếu được đóng trong container thùng kín, dẫn đến các cuộn cáp điện bên trong container sẽ bị gãy ván gỗ của cuộn cáp, có thể dẫn đến hàng hóa cáp điện bị xô lệch về một bên của xe, rất nguy hiểm nếu hàng hóa bị xô lệch về một bên.</span></p><div id=\\\"attachment_1428\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1428\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1428 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-6.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-6.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-6-768x576.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1428\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh nhiều cuộn cáp điện nhỏ nhỏ cần vận chuyển, thì trước đó phải được để lên pallet đóng gói cẩn thận, xung quanh được bọc carton để hạn chế các kiện hàng xếp khít vào nhau sẽ không bị trầy xước, lưu ý rằng hàng hóa cáp điện trên pallet không được dư ra khỏi pallet mà bắt buộc phải nằm trên và bên trong pallet, nếu cáp điện giá trị quá cao và dễ hư hỏng thì tốt nhất nên đóng gói bằng cách thêm kiện gỗ xuong quanh bên ngoài pallet để đảm bảo tuyệt đối hàng hóa cáp điện bên trong sẽ được an toàn khi vận chuyển hàng hóa đường dài bắc nam bằng xe tải thùng hoặc xe đầu kéo container )</p></div><h2 data-header=\\\"3\\\" id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(255, 255, 255);\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Kinh nghiệm vận chuyển cáp điện cốt lỗi?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hiện tại vấn đề về<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>(<strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện)<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span></strong>rất được ít trú trọng, có rất nhiều<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">công ty vận tải hàng hóa</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>cứ nghĩ cáp điện là mặt hàng cứng, nặng, không bao giờ hư hỏng, đây là một suy nghĩ hoàn toàn sai lầm cần phải được sữa chữa ngay lập tức. Vì chỉ cần lơ là một chút ở kỹ thuật chằng buộc có thể dẫn đến hậu quả nghiêm trọng.</span></p><div id=\\\"attachment_1427\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1427\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1427 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-5.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-5.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-5-768x576.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1427\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh nhiều cuộn cáp điện nhỏ nhỏ cần vận chuyển, thì trước đó phải được để lên pallet đóng gói cẩn thận, xung quanh được bọc carton để hạn chế các kiện hàng xếp khít vào nhau sẽ không bị trầy xước, lưu ý rằng hàng hóa cáp điện trên pallet không được dư ra khỏi pallet mà bắt buộc phải nằm trên và bên trong pallet)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Trong thực tế, Chành xe Phú Quốc – Con Rùa Biển đã trải qua<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">nhiều năm kinh nghiệm vận chuyển thực tế mặt hàng cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>này, không có ít lần xảy ra sự cố hư hỏng gỗ cáp điện, nhưng chỉ là những hư hỏng nhẹ, không nghiêm trọng, nhưng công ty luôn coi đây là những trường hợp cần phải khắc phục và đúc kết<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>về sau về lâu dài để ngày càng vận chuyển mặt hàng một cách tốt nhất và an toàn nhất.</span></p><div id=\\\"attachment_1429\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1429\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1429 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-7.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"1347\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-7.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-7-768x431.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1429\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh nhiều cuộn cáp điện được xếp lên một xe đầu kéo để vận chuyển, tuy nhiên ảnh này là hình ảnh di chuyển cáp điện trong bãi chứa hàng hóa từ vị trí này sang vị trí khác không phải là xe vận chuyển tham gia giao thông ngoài đường, ảnh này để cho mọi người thấy khi vận chuyển cáp điện bằng đầu kéo romooc sàn không được xếp hàng theo dạng này, vì rất là nguy hiểm nếu tham gia giao thông ngoài đường. Mọi người khi vận chuyển tuyệt đối không được xếp hàng cáp điện theo dạng này)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; font-size: 14px; line-height: 22px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; background-color: rgb(255, 255, 255); text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Mỗi một hình ảnh bên dưới đây sẽ được chia sẽ với Quý khách hàng và đối tác để mọi người có thể hiểu rõ về sự an toàn cũng như là<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong><span style=\\\"box-sizing: border-box;\\\">&nbsp;</span>là rất quan trọng. Bên dưới mỗi tấm ảnh Chúng tôi sẽ có diễn giải chi tiết cụ thể.</span></p><div id=\\\"attachment_1434\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1434\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1434 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-12.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-12.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-12-768x432.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1434\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp điện; Trong ảnh là cảnh cuộn cáp điện đã được đóng vào xe đầu kéo container để vận chuyển đường dài. Hàng cáp điện trên xe đã được đóng gỗ chèn lót rất cẩn thận và còn được ràng buộc thêm dây cảo để hàng cáp điện được tuyệt đối an toàn khi vận chuyển đường dài, trong hình có rất nhiều ván gỗ được đóng để giữ cáp điện điện cố định, ngoài ra Cty vận tải Con Rùa Biển còn kỹ hơn, đã cho nhân viên dùng dây cảo loại lớn để chằng buộc thêm vào cuộn cáp điện, để tuyệt đối cuộn cáp điện phải được cố định một chỗ khi xe di chuyển. Nhìn vào hình có thể thấy cuộn cáp điện không thể lăn trái hay phải, hay lăn trước hoặc sau, vì đã có gỗ chèn lót và dây cảo lớn đã được buộc chặc. Đây là công đoạn rất quan trọng để vận chuyển hàng hóa cáp điện an toàn đi đường dài bắc nam hoặc xuất hàng đường biển đi quốc tế)</p></div><div id=\\\"attachment_1433\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1433\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-1433 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-11.jpg\\\" alt=\\\"ảnh chia sẽ kinh nghiệm vận chuyển cáp điện\\\" width=\\\"2400\\\" height=\\\"3200\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-11.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-11-768x1024.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1433\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong>; Trong ảnh là cảnh cuộn cáp điện đã được đóng vào xe đầu kéo container để vận chuyển đường dài. Hàng cáp điện trên xe đã được đóng gỗ chèn lót rất cẩn thận và còn được ràng buộc thêm dây cảo để hàng cáp điện được tuyệt đối an toàn khi vận chuyển đường dài.)</p></div><div id=\\\"attachment_1423\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1423\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-1423\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-1.jpg\\\" alt=\\\"Hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp diện loại kích thước lớn và tải trọng lớn 1\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-1.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-1-768x432.jpg 768w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; border: 0px none; vertical-align: middle; max-width: 100%; position: relative; height: auto; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-1423\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Ảnh: Cty Con Rùa Biển hướng dẫn và chia sẽ<span style=\\\"box-sizing: border-box;\\\">&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">kinh nghiệm vận chuyển cáp điện</strong>; Trong ảnh là cảnh công nhân đóng gỗ để chèn lót cáp điện bên trong container thùng kín khi vận chuyển đường dài Bắc Nam, chén lót như thế sẽ làm cho cáp điện không bị lăn, lăn trái phải hay trước sau điều không xảy ra sự cố, nếu không chèn lót như thế rất nguy hiểm nếu như cáp điện lăn)</p></div><div id=\\\"attachment_1425\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1425\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-1425\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/H%C6%B0%E1%BB%9Bng-d%E1%BA%ABn-v%C3%A0-chia-s%E1%BA%BD-kinh-nghi%E1%BB%87m-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-di%E1%BB%87n-lo%E1%BA%A1i-k%C3%ADch-th%C6%B0%E1%BB%9Bc-l%E1%BB%9Bn-v%C3%A0-t%E1%BA%A3i-tr%E1%BB%8Dng-l%E1%BB%9Bn-3.jpg\\\" alt=\\\"Hướng dẫn và chia sẽ kinh nghiệm vận chuyển cáp diện loại kích thước lớn và tải trọng lớn 3\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-trọng-lớn-3.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/06/Hướng-dẫn-và-chia-sẽ-kinh-nghiệm-vận-chuyển-cáp-diện-loại-kích-thước-lớn-và-tải-t