INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (295,3,'CHO THUÊ XE TẢI ĐI PHÚ QUỐC GIÁ RẺ','Phú Quốc là hòn đảo lớn nhất Việt Nam và thuận lợi để phát triển kinh tế khi sở hữu tài nguyên rừng vàng biển bạc. Với tốc độ tăng trưởng kinh tế vượt bậc, hiện nay nhu cầu vận chuyển hàng hóa đi Phú Quốc ngày càng nhiều. Nắm bắt được xu thế đó,…','https://conruabien.vn/wp-content/uploads/2021/03/DICH-VU-VAN-CHUYEN-HANG-HOA-DI-MIEN-TAY-CHO-THUE-XE-CAU-TAI-PHU-QUOC-2.jpg','\"<p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Phú Quốc là hòn đảo lớn nhất Việt Nam và thuận lợi để phát triển kinh tế khi sở hữu tài nguyên rừng vàng biển bạc. Với tốc độ tăng trưởng kinh tế vượt bậc, hiện nay nhu cầu vận chuyển hàng hóa đi Phú Quốc ngày càng nhiều. Nắm bắt được xu thế đó,<span>&nbsp;</span><a href=\\\"https://conruabien.vn/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">CÔNG TY TNHH DỊCH VỤ HÀNG HÓA CON RÙA BIỂN<span>&nbsp;</span></strong></a>đã đẩy mạnh<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">dịch vụ cho thuê xe tải đi Phú Quốc</em></strong><span>&nbsp;</span>để phục vụ nhu cầu vận chuyển hàng hóa nội địa đi Phú Quốc một cách an toàn, chuyên nghiệp, giá rẻ.</span></p><div id=\\\"attachment_3344\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-3344\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-3344\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-13.jpg\\\" alt=\\\"Cho thue xa lan ha mom cho xe tai cho xe dau keo container di Phu Quoc Hon Thom Nam Du 13\\\" width=\\\"2400\\\" height=\\\"1468\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-13.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-13-768x470.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-13-1536x940.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-13-2048x1253.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3344\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển là Chành xe Hà Nội Sài Gòn Phú Quốc chạy chuyên tuyến, có lịch xe chạy cố định hằng ngày, nhận vận chuyển hàng lẻ đi ghép hoặc hàng bao xe. Đặc biệt còn cung cấp dịch vụ vận tải hàng hóa bằng đường thủy theo hình thức: cho thuê xà lan, cho thuê tàu biển, cho thuê phà đi biển, cho thuê xà lan há mòm chở xe tải, xe đầu kéo container từ đất liền đi Đảo Phú Quốc, Đảo Hòn Thơm, Đảo Nam Du, Đảo Thổ Châu, Đảo Hòn Trẻ, Đảo Hòn Sơn.</p></div><div id=\\\"attachment_517\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-517\\\" decoding=\\\"async\\\" class=\\\"wp-image-517 size-full\\\" title=\\\"(Ảnh: Bãi xe HCM, Chành xe Phú Quốc công ty CON RÙA BIỂN có nhiều loại xe tải từ 8 tấn, 15 tấn, 20 tấn và đầu kéo container , cho thuê xe tải nguyên chiếc)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-2.jpg\\\" alt=\\\"(Ảnh: Bãi xe HCM, Chành xe Phú Quốc công ty CON RÙA BIỂN có nhiều loại xe tải từ 8 tấn, 15 tấn, 20 tấn và đầu kéo container , cho thuê xe tải nguyên chiếc)\\\" width=\\\"1024\\\" height=\\\"619\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-2.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-2-768x464.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-517\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">(Ảnh: Bãi xe HCM, Chành xe Phú Quốc công ty CON RÙA BIỂN có nhiều loại xe tải từ 8 tấn, 15 tấn, 20 tấn và đầu kéo container , cho thuê xe tải nguyên chiếc)</p></div><div id=\\\"attachment_5060\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5060\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5060\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-69-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 69 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-69-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-69-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-69-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-69-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-5060\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển – Chành xe Hà Nội Sài Gòn Phú Quốc là nhà xe chuyên vận chuyển hàng hóa đi Phú Quốc bằng xe tải, xe đầu kéo container; trong ảnh là cảnh đội bốc xếp tại Kho Con Rùa Biển HCM bốc xếp hàng hóa dưới đất lên xe tải và sắp xếp. Nguyên tắt quan trọng nhất trong khâu sắp xếp là đảm bảo tuyệt đối các loại hàng hóa đi ghép trên cùng một xe tải phải luôn được đảm bảo an toàn 100% ra đến đảo Phú Quốc giao cho khách hàng. ĐỘI BỐC XẾP LÀM VIỆC XUYÊN ĐÊM ĐỂ ĐẢM BẢO TIẾN ĐỘ THỜI GIAN VÀ AN TOÀN HÀNG HÓA.</p></div><div id=\\\"attachment_5043\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5043\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5043\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-53-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 53 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-53-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-53-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-53-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-53-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-5043\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển – Chành xe Hà Nội Sài Gòn Phú Quốc là nhà xe chuyên vận chuyển hàng hóa đi Phú Quốc bằng xe tải, xe đầu kéo container; trong ảnh là mặt hàng vật liệu xây dựng, bồn cầu, gốm sứ, gạch men, máy lạnh, máy làm mát, lốp xe, vải địa, đế dù, chân dù, cây dù, bình ác quy, bột trét, xi măng … đã được nhân viên Con Rùa Biển sắp xếp lên xe tải loại 15 tấn tại Kho HCM gồm nhiều loại sản phẩm khác nhau trên cùng một chuyến xe, trong vận chuyển cách sắp xếp hàng hóa là một trong những khâu rất quan trọng để đảm bảo hàng hóa an toàn trong quá trình vận chuyển đường dài bằng xe tải đi đường bộ kết hợp đường biển. HÀNG HÓA LÊN XE TẢI LÀ PHẢI ĐƯỢC RÀNG BUỘC CẨN THẬN TUYỆT ĐỐI, ĐỂ ĐẢM BẢO AN TOÀN</p></div><div id=\\\"attachment_5030\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5030\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5030\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-40.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 40\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-40.jpg 2400w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-40-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-40-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-40-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-5030\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển – Chành xe Hà Nội Sài Gòn Phú Quốc là nhà xe chuyên vận chuyển hàng hóa đi Phú Quốc bằng xe tải, xe đầu kéo container; trong ảnh là mặt hàng vật liệu xây dựng, bồn cầu, gốm sứ, gạch men, máy lạnh, máy làm mát, lốp xe, vải địa, đế dù, chân dù, cây dù, bình ác quy, bột trét, xi măng … đã được nhân viên Con Rùa Biển sắp xếp lên xe tải loại 15 tấn tại Kho HCM gồm nhiều loại sản phẩm khác nhau trên cùng một chuyến xe, trong vận chuyển cách sắp xếp hàng hóa là một trong những khâu rất quan trọng để đảm bảo hàng hóa an toàn trong quá trình vận chuyển đường dài bằng xe tải đi đường bộ kết hợp đường biển.</p></div><h1 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-weight: normal !important; font-size: 30px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-size: 14pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">I-Những thông tin chi tiết về<span>&nbsp;</span><a href=\\\"https://conruabien.vn/cho-thue-xe-tai/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(10, 10, 10); text-decoration: none;\\\">dịch vụ cho thuê xe tải đi Phú Quốc</a><span>&nbsp;</span>của Con Rùa Biển</strong></span></h1><h2 id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-weight: normal !important; font-size: 24px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-size: 12pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">1.1 Cho thuê xe tải theo chuyến</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đây là hình thức<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">cho thuê xe tải</strong><span>&nbsp;</span>chở hàng hóa tính trọn gói theo chuyến mà bạn không cần phải lo lắng về km đồng hồ. Sẽ không có cước phí phát sinh. Và cước phí sẽ tùy thuộc vào trọng tải của xe và quãng đường vận chuyển.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Cho thuê xe tải theo chuyến hay còn gọi là dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">cho thuê xe tải đi Phú Quốc</strong>&nbsp;bao xe nguyên chiếc, Con Rùa Biển nhận được thông tin của Quý Khách hàng có nhu cầu<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">bao xe trọn gói</strong><span>&nbsp;</span>từ Nơi gửi đến Nơi giao sẽ được chốt 1 giá cụ thể trọn gói không phát sinh chi phí dọc đường.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Thông thường nếu đi hàng nhẹ Quý khách hàng nên chọn loại xe 15 tấn là tối ưu nhất. Kích thước xe “dài 9.2m rộng 2.3m cao 2.3m”</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nếu Quý khách hàng cần vận chuyển hàng nặng như sắt thép hay gạch men … thì nên sử dụng dịch vụ<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cho thuê xe tải đi Phú Quốc</strong><span>&nbsp;</span>áp dụng cho dòng xe tải 20 tấn là phương án tối ưu nhất khi<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">vận chuyển hàng hóa đi Phú Quốc</strong>, kích thước xe tải 20 tấn là “dài 9.4m rộng 2.3m cao 2.3m”</span></p><div id=\\\"attachment_3331\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-3331\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3331\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-tai-di-Phu-Quoc-12.jpg\\\" alt=\\\"Cho thue xa lan cho xe tai di Phu Quoc 12\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-tai-di-Phu-Quoc-12.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-tai-di-Phu-Quoc-12-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-tai-di-Phu-Quoc-12-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-tai-di-Phu-Quoc-12-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3331\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển là Chành xe Hà Nội Sài Gòn Phú Quốc chạy chuyên tuyến, có lịch xe chạy cố định hằng ngày, nhận vận chuyển hàng lẻ đi ghép hoặc hàng bao xe. Đặc biệt còn cung cấp dịch vụ vận tải hàng hóa bằng đường thủy theo hình thức: cho thuê xà lan, cho thuê tàu biển, cho thuê phà đi biển, cho thuê xà lan há mòm chở xe tải, xe đầu kéo container từ đất liền đi Đảo Phú Quốc, Đảo Hòn Thơm, Đảo Nam Du, Đảo Thổ Châu, Đảo Hòn Trẻ, Đảo Hòn Sơn.</p></div><div id=\\\"attachment_512\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-512\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-512 size-full\\\" title=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang nhận máy móc thiết bị hạng nặng từ HCM đi Phú Quốc)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-7.jpg\\\" alt=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang cung cấp dịch vụ cho thuê xe tải đi Phú Quốc\\\" width=\\\"1024\\\" height=\\\"865\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-7.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-7-768x649.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-512\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang nhận máy móc thiết bị hạng nặng từ HCM đi Phú Quốc)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><img decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"alignnone size-full wp-image-5083\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-92-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 92 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-92-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-92-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-92-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-92-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px; vertical-align: middle; margin: 5px 20px 20px 0px;\\\"><span>&nbsp;</span><img decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"alignnone size-full wp-image-5081\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-90-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 90 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-90-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-90-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-90-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-90-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px; vertical-align: middle; margin: 5px 20px 20px 0px;\\\"></p><h2 id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-weight: normal !important; font-size: 24px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-size: 12pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">1.2<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Cho thuê xe tải đi Phú Quốc theo hợp đồng dài hạn</span></strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Hình thức cho thuê xe tải này thích hợp với những đối tác là công ty, xí nghiệp lớn, muốn làm ăn lâu dài và tiết kiệm chi phí cho thuê xe theo hợp đồng dài hạn.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khi ký hợp đồng dài hạn giữa Khách hàng và Con Rùa Biển thì khách hàng sẽ nhận được rất nhiều ưu đãi. Cụ thể là đã có giá thấp hơn 10% so với giá công bố.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khi có nhu cần về bảo hiểm hàng hóa, Con Rùa Biển sẽ hỗ trợ và tư vấn mua bảo hiểm hàng hóa với cám kết chi phí bảo hiểm thấp nhất và quyền lợi được hưởng đầy đủ 100% giá trị hàng hóa.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ưu tiên cho khách hàng ký hợp đồng dài hạn về thời gian vận chuyển, thời gian giao nhận tận nơi luôn luôn nhanh nhất.</span></p><div id=\\\"attachment_3319\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-3319\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3319\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-12.jpg\\\" alt=\\\"Cho thue xa lan cho xe dau keo container di Phu Quoc 12\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-12.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-12-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-12-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-12-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3319\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển là Chành xe Hà Nội Sài Gòn Phú Quốc chạy chuyên tuyến, có lịch xe chạy cố định hằng ngày, nhận vận chuyển hàng lẻ đi ghép hoặc hàng bao xe. Đặc biệt còn cung cấp dịch vụ vận tải hàng hóa bằng đường thủy theo hình thức: cho thuê xà lan, cho thuê tàu biển, cho thuê phà đi biển, cho thuê xà lan há mòm chở xe tải, xe đầu kéo container từ đất liền đi Đảo Phú Quốc, Đảo Hòn Thơm, Đảo Nam Du, Đảo Thổ Châu, Đảo Hòn Trẻ, Đảo Hòn Sơn.</p></div><div id=\\\"attachment_513\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-513\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-513 size-full\\\" title=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang nhận hàng kết cấu thép từ HCM đi ra đảo Phú Quốc, cho thuê xe tải đi Phú Quốc nguyên chiếc)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-8.jpg\\\" alt=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang nhận hàng kết cấu thép từ HCM đi ra đảo Phú Quốc, cho thuê xe tải đi Phú Quốc nguyên chiếc)\\\" width=\\\"1024\\\" height=\\\"768\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-8.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-8-768x576.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-513\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang nhận hàng kết cấu thép từ HCM đi ra đảo Phú Quốc, cho thuê xe tải nguyên chiếc)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><img decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"alignnone size-full wp-image-5078\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-87.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 87\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-87.jpg 2400w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-87-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-87-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-87-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px; vertical-align: middle; margin: 5px 20px 20px 0px;\\\"></p><div id=\\\"attachment_5065\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5065\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5065\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-74-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 74 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-74-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-74-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-74-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-74-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-5065\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển – Chành xe Hà Nội Sài Gòn Phú Quốc là nhà xe chuyên vận chuyển hàng hóa đi Phú Quốc bằng xe tải, xe đầu kéo container; trong ảnh là cảnh đội bốc xếp tại Kho Con Rùa Biển HCM bốc xếp hàng hóa dưới đất lên xe tải và sắp xếp. Nguyên tắt quan trọng nhất trong khâu sắp xếp là đảm bảo tuyệt đối các loại hàng hóa đi ghép trên cùng một xe tải phải luôn được đảm bảo an toàn 100% ra đến đảo Phú Quốc giao cho khách hàng. ĐỘI BỐC XẾP LÀM VIỆC XUYÊN ĐÊM ĐỂ ĐẢM BẢO TIẾN ĐỘ THỜI GIAN VÀ AN TOÀN HÀNG HÓA.</p></div><h2 id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-weight: normal !important; font-size: 24px;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-size: 12pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">1.3<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ưu thế dịch vụ cho thuê xe tải của Công ty vận tải Con Rùa Biển</span></strong></span></h2><ul style=\\\"box-sizing: border-box; margin-top: 0px; margin-bottom: 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 14px;\\\"><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cho thuê xe tải đi Phú Quốc</strong><span>&nbsp;</span>với nhiều dòng xe tải đa dạng: xe tải 2 tấn, xe tải 5 tấn, xe tải 15 tấn, xe tải 20 tấn</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Ngoài xe tải còn có dịch vụ mở rộng: cho thuê xe cẩu loại 5 tấn, xe cẩu loại 15 tấn, xe cẩu loại 20 tấn hoặc xe cẩu kato 25 tấn, xe cẩu kato 45 tấn, xe cẩu kato 75 tấn, xe cẩu kato 125 tấn.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Kho bãi rộng rãi, thoáng mát, có&nbsp;đầy&nbsp;đủ các thiết bị nâng, hạ giúp việc bốc xếp dễ dàng.</span></li><li style=\\\"box-sizing: border-box;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Cho thuê xe tải đi Phú Quốc</strong><span>&nbsp;</span>liên tục hằng ngày, từ Sài Gòn đi Phú Quốc sẽ có ít nhất là<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">2 chuyến/ngày</strong>. Do đó quý khách có thể yên tâm về tiến&nbsp;độ và thời gian giao hàng, không sợ bị lưu kho.</span></li></ul><div id=\\\"attachment_3311\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-3311\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3311\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-4.jpg\\\" alt=\\\"Cho thue xa lan cho xe dau keo container di Phu Quoc 4\\\" width=\\\"2400\\\" height=\\\"1468\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-4.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-4-768x470.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-4-1536x940.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-cho-xe-dau-keo-container-di-Phu-Quoc-4-2048x1253.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3311\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển là Chành xe Hà Nội Sài Gòn Phú Quốc chạy chuyên tuyến, có lịch xe chạy cố định hằng ngày, nhận vận chuyển hàng lẻ đi ghép hoặc hàng bao xe. Đặc biệt còn cung cấp dịch vụ vận tải hàng hóa bằng đường thủy theo hình thức: cho thuê xà lan, cho thuê tàu biển, cho thuê phà đi biển, cho thuê xà lan há mòm chở xe tải, xe đầu kéo container từ đất liền đi Đảo Phú Quốc, Đảo Hòn Thơm, Đảo Nam Du, Đảo Thổ Châu, Đảo Hòn Trẻ, Đảo Hòn Sơn.</p></div><div id=\\\"attachment_514\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1034px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-514\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"wp-image-514 size-full\\\" title=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang giao hàng thiết bị bóng đèn cho Sân Bay Phú Quốc từ HCM đi ra đảo Phú Quốc, cho thuê xe tải nguyên chiếc)\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-9.jpg\\\" alt=\\\"(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang giao hàng thiết bị bóng đèn cho Sân Bay Phú Quốc từ HCM đi ra đảo Phú Quốc, cho thuê xe tải nguyên chiếc)\\\" width=\\\"1024\\\" height=\\\"576\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-9.jpg 1024w, https://conruabien.vn/wp-content/uploads/2021/03/CHO-THUE-XE-TAI-TU-HCM-DI-PHU-QUOC-9-768x432.jpg 768w\\\" sizes=\\\"(max-width: 1024px) 100vw, 1024px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-514\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">(Ảnh: Chành xe Phú Quốc công ty CON RÙA BIỂN đang giao hàng thiết bị bóng đèn cho Sân Bay Phú Quốc từ HCM đi ra đảo Phú Quốc, cho thuê xe tải nguyên chiếc)</p></div><div id=\\\"attachment_5053\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5053\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5053\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-63-scaled.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 63 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-63-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-63-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-63-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-63-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-5053\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; line-height: 17px; padding: 5px; font-size: 11px;\\\">Con Rùa Biển – Chành xe Hà Nội Sài Gòn Phú Quốc là nhà xe chuyên vận chuyển hàng hóa đi Phú Quốc bằng xe tải, xe đầu kéo container; trong ảnh là mặt hàng vật liệu xây dựng, bồn cầu, gốm sứ, gạch men, máy lạnh, máy làm mát, lốp xe, vải địa, đế dù, chân dù, cây dù, bình ác quy, bột trét, xi măng … đã được nhân viên Con Rùa Biển sắp xếp lên xe tải loại 15 tấn tại Kho HCM gồm nhiều loại sản phẩm khác nhau trên cùng một chuyến xe, trong vận chuyển cách sắp xếp hàng hóa là một trong những khâu rất quan trọng để đảm bảo hàng hóa an toàn trong quá trình vận chuyển đường dài bằng xe tải đi đường bộ kết hợp đường biển. HÀNG HÓA LÊN XE TẢI LÀ PHẢI ĐƯỢC RÀNG BUỘC CẨN THẬN TUYỆT ĐỐI, ĐỂ ĐẢM BẢO AN TOÀN</p></div><div id=\\\"attachment_5050\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px; font-size: 14px;\\\"><img aria-describedby=\\\"caption-attachment-5050\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-5050\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-di-Phu-Quoc-thoi-gian-nhanh-60.jpg\\\" alt=\\\"Nhan ghep hang nho le di Phu Quoc thoi gian nhanh 60\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2023/02/Nhan-ghep-hang-nho-le-