INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (306,2,'GIAO HÀNG NHANH TIẾT KIỆM ĐI PHÚ QUỐC TỪ SÀI GÒN | 0945000006','Giao hàng nhanh tiết kiệm đi Phú Quốc từ Sài Gòn là dịch vụ ưu việt nên này càng có nhiều khách hàng lựa chọn khi có nhu cầu. Trong đó, có nhiều người thắc mắc dịch vụ Giao hàng nhanh tiết kiệm đi Phú Quốc từ Sài Gòn giới hạn loại hàng hoá nào hay không?','https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-41-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Giao hàng nhanh tiết kiệm đi Phú Quốc từ Sài Gòn nhận những loại hàng hoá nào?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thic