INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (337,2,'5 Phương thức Vận chuyển hàng hóa Quốc tế | CON RÙA BIỂN','Khám phá ngay 5 phương thức vận chuyển hàng hoá quốc tế Phương thức vận chuyển hàng hoá quốc tế có khác biệt so với nội địa hay không...','https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-68-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Khám phá ngay 5 phương thức vận chuyển hàng hoá quốc tế</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Phương thức vận chuyển hàng hoá quốc tế có khác biệt so với nội địa hay không? Vậy cùng khám ngay<span>&nbsp;</span><a data-mil=\\\"3784\\\" href=\\\"https://conruabien.vn/tin-tuc/5-phuong-thuc-van-chuyen-hang-hoa-quoc-te-con-rua-bien/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">5 phương thức vận chuyển hàng hoá quốc tế</a><span>&nbsp;</span>phổ biến dưới đây để thấy rõ sự khác biệt.</strong></span></p><h2 id=\\\"ftoc-heading-2\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Phương thức vận chuyển đường bộ (roadways)</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><a href=\\\"http://vantainoidia.vn/dich-vu/cho-thue-xe-tai-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Vận chuyển hàng hoá đường bộ</a><span>&nbsp;</span>luôn là lựa chọn phổ biến dù là nội địa. Còn vận chuyển quốc tế thì sao?<span>&nbsp;</span><a data-mil=\\\"3784\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/chuyen-phat-nhanh-quoc-te/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Vận chuyển quốc tế</a><span>&nbsp;</span>bằng đường bộ cũng thuộc 1 trong những phương thức được các đơn vị lựa chọn khi có nhu cầu. Nhưng người tiêu dùng cũng nên cân nhắc lựa chọn sao cho phù hợp. Bởi vận chuyển quốc tế đường bộ có nhược điểm là phụ thuộc nhiều vào hệ thống đường được xây dựng trước đó.</span></p><div id=\\\"attachment_3687\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3687\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-3687\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-67.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 67\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-67.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-67-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-67-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-67-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3687\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất của Khách hàng đem ra chành xe Phú Quốc tại HCM, để gửi hàng nội thất đi Phú Quốc theo hình thức đi ghép xe tải cùng với nhiều loại hàng hóa khác để tiết kiệm chi phí vận chuyển, đây là hình thức đi ghép phổ biến nhất hiện nay tại chành xe chuyến tuyến đi Phú Quốc, và cũng cứ mỗi buổi chiều hằng ngày anh em công nhân của bãi xe đã xếp hàng hóa các loại lên xe tải để đi ghép qua phú quốc hằng ngày, hằng ngày bắt đầu xếp hàng lên xe từ lúc chiều cho đến nữa đêm hay đến khi nào xong hàng mới nghĩ)</p></div><div id=\\\"attachment_3742\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3742\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-3742\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/10/van-chuyen-hang-bang-may-bay-1.jpg\\\" alt=\\\"van chuyen hang bang may bay 1\\\" width=\\\"2400\\\" height=\\\"1320\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/10/van-chuyen-hang-bang-may-bay-1.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/10/van-chuyen-hang-bang-may-bay-1-768x422.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/10/van-chuyen-hang-bang-may-bay-1-1536x845.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/10/van-chuyen-hang-bang-may-bay-1-2048x1126.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3742\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh vận chuyển hàng không tại Sân Bay Tân Sơn Nhất, chuyển phát nhanh bằng đường hàng không, vận chuyển hàng hóa bằng máy bay từ Sài Gòn đi Phú Quốc)</p></div><div id=\\\"attachment_3668\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3668\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3668\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-48.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 48\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-48.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-48-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-48-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-48-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3668\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất của Khách hàng đem ra chành xe Phú Quốc tại HCM, để gửi hàng nội thất đi Phú Quốc theo hình thức đi ghép xe tải cùng với nhiều loại hàng hóa khác để tiết kiệm chi phí vận chuyển, đây là hình thức đi ghép phổ biến nhất hiện nay tại chành xe chuyến tuyến đi Phú Quốc, và cũng cứ mỗi buổi chiều hằng ngày anh em công nhân của bãi xe đã xếp hàng hóa các loại lên xe tải để đi ghép qua phú quốc hằng ngày, hằng ngày bắt đầu xếp hàng lên xe từ lúc chiều cho đến nữa đêm hay đến khi nào xong hàng mới nghĩ)</p></div><div id=\\\"attachment_3521\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3521\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3521\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Nhan-gui-may-bom-nho-le-di-Ha-Noi-20.jpg\\\" alt=\\\"Nhan gui may bom nho le di Ha Noi 20\\\" width=\\\"2400\\\" height=\\\"2233\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Nhan-gui-may-bom-nho-le-di-Ha-Noi-20.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Nhan-gui-may-bom-nho-le-di-Ha-Noi-20-768x715.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Nhan-gui-may-bom-nho-le-di-Ha-Noi-20-1536x1429.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Nhan-gui-may-bom-nho-le-di-Ha-Noi-20-2048x1905.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3521\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Máy Bơm đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN. Trong ảnh là cảnh hàng hóa thiết bị máy bơm được đóng kiện gỗ cẩn thận nhập về cảng cát lái HCM, được xe tải đi lấy đưa về kho HCM, sau đó kết hợp vận chuyển đi ghép xe máy bơm với nhiều loại hàng hóa khác ra đảo Phú Quốc để tiết kiệm chi phí vận chuyển)</p></div><div id=\\\"attachment_3494\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3494\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3494\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-van-chuyen-may-bom-di-Phu-Quoc-cua-Du-an-SunHome-1.jpg\\\" alt=\\\"Du an van chuyen may bom di Phu Quoc cua Du an SunHome 1\\\" width=\\\"2400\\\" height=\\\"1969\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-van-chuyen-may-bom-di-Phu-Quoc-cua-Du-an-SunHome-1.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-van-chuyen-may-bom-di-Phu-Quoc-cua-Du-an-SunHome-1-768x630.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-van-chuyen-may-bom-di-Phu-Quoc-cua-Du-an-SunHome-1-1536x1260.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-van-chuyen-may-bom-di-Phu-Quoc-cua-Du-an-SunHome-1-2048x1680.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3494\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Máy Bơm Grundfos đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN ở Khu Công Trình cáp treo An Thới Hòn Thơm Phú Quốc Kiên Giang. Nội dung công việc thực hiện là Cho thuê xe tải nguyên chiếc (bao xe) chở máy bơm từ người bán ở HCM đi qua đảo Phú Quốc, giao hàng tận chân công trình, rút hàng, cẩu hạ máy bơm từ xe tải xuống đất, đúng vị trí tập kết đã được thỏa thuận trước. Trong ảnh là cảnh xe cẩu thùng 20 tấn đang cẩu hạ máy bơm từ xe tải cẩu xuống đất, trước đó là xe cẩu này đang cẩu máy bơm sang xe từ xe tải 20 tấn đang đầu ngoài cổng công trình, do xe 20 tấn không thể di chuyển vào bên trong, nên phải sang xe nhỏ hơn là xe cẩu 20 tấn để thuận lợi giao hàng nhanh)</p></div><h2 id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Phương thức vận chuyển đường biển (Ocean shipping)</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><a data-mil=\\\"3784\\\" href=\\\"https://conruabien.vn/dich-vu-mo-rong/van-chuyen-hang-hoa-duong-bien/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Vận tải đường biển</a><span>&nbsp;</span>ra đời từ rất sớm và đã được các quốc gia ứng dụng phổ biến trong việc lưu thông hàng hoá. Hiện nay, vận tải đường biển quốc tế vẫn là sự lựa chọn hàng đầu của các cá nhân, doanh nghiệp. &nbsp;</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Vận tải hàng hoá quốc tế bằng&nbsp; đường biển phù hợp với loại hàng hoá lâu hỏng, cồn kềnh, có giá trị thấp, hàng rời và những loại hàng hoá không có đòi hỏi thời gian giao hàng cấp tốc.</span></p><div id=\\\"attachment_3461\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3461\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3461\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-11.jpg\\\" alt=\\\"Du an Van chuyen thang may di Phu Quoc cua Mariot 11\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-11.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-11-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-11-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-11-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3461\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Thang Máy Băng Tải đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN ở khu Công trình JW Marriott Phu Quoc Emerald Bay. Hình thức vận chuyển là dùng Xe đầu kéo container sẽ vận chuyển Container từ Cảng Cát Lái HCM đi Phú Quốc chở hàng Thang Máy Băng Tải – vật tư thiết bị công trình, giao hàng tại đây và kèm theo dịch vụ mở rộng Cho thuê xe cẩu 20 tấn nhận rút hàng container và di chuyển hàng vào vị trí lắp đặt thang máy tại Công trình. Trong ảnh là cảnh xe cẩu 20 tấn đang rút hàng từ trong container ra ngoài và hạ hàng thiết bị thang máy xuống bãi tập kết, sau đó kiểm tra lại trước khi di chuyển vào vị trí lắp đặt)</p></div><div id=\\\"attachment_3404\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1450px;\\\"><img aria-describedby=\\\"caption-attachment-3404\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3404\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-41-scaled.jpg\\\" alt=\\\"Du an Van chuyen May Giat Say Cong Nghiep di Phu Quoc 41 scaled\\\" width=\\\"1440\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-41-scaled.jpg 1440w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-41-768x1365.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-41-864x1536.jpg 864w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-41-1152x2048.jpg 1152w\\\" sizes=\\\"(max-width: 1440px) 100vw, 1440px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3404\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh: Dự Án vận chuyển Máy Giặt Sấy Công Nghiệp đi Phú Quốc tại Chành xe Hà Nội Đà Nẵng Sài Gòn Phú Quốc ở cty CON RÙA BIỂN cho Dự án Premier Village Phu Quoc Resort; trong ảnh là cảnh Máy Giặt Sấy Công Nghiệp đang nằm ở ngay cửa ra vào của tầng hầm nhà để máy giặt sấy công nghiệp, cửa hầm thấp, máy giặt sấy thì cao và nặng, nên để đưa vào được cũng là một vấn đề cực kỳ khó, nên chỉ có cách là dùng kết hợp nhiều thiết bị mới có thể đưa vào được khỏi vị trí này, xe nâng tay + xe nâng máy kéo)</p></div><div id=\\\"attachment_3381\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3381\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3381\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-18.jpg\\\" alt=\\\"Du an Van chuyen May Giat Say Cong Nghiep di Phu Quoc 18\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-18.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-18-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-18-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-May-Giat-Say-Cong-Nghiep-di-Phu-Quoc-18-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3381\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh: Dự Án vận chuyển Máy Giặt Sấy Công Nghiệp đi Phú Quốc tại Chành xe Hà Nội Đà Nẵng Sài Gòn Phú Quốc ở cty CON RÙA BIỂN, thuộc Dự án Nhà máy Kasa Laundry Phú Quốc; trong ảnh là cảnh vị trị sẽ phải đưa những kiện hàng Máy Giặt Sấy Công Nghiệp vào vị trí, trong khu nhà này vào sâu bên trong nên các phương tiện chuyên dụng như xe nâng máy không thể vào, nên dùng sức và tời kéo, con lăn, con đổi để đưa máy vào vị trí, vô cùng khó khăn)</p></div><div id=\\\"attachment_3338\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3338\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3338\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-7.jpg\\\" alt=\\\"Cho thue xa lan ha mom cho xe tai cho xe dau keo container di Phu Quoc Hon Thom Nam Du 7\\\" width=\\\"2400\\\" height=\\\"1468\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-7.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-7-768x470.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-7-1536x940.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Cho-thue-xa-lan-ha-mom-cho-xe-tai-cho-xe-dau-keo-container-di-Phu-Quoc-Hon-Thom-Nam-Du-7-2048x1253.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3338\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">Con Rùa Biển là Chành xe Hà Nội Sài Gòn Phú Quốc chạy chuyên tuyến, có lịch xe chạy cố định hằng ngày, nhận vận chuyển hàng lẻ đi ghép hoặc hàng bao xe. Đặc biệt còn cung cấp dịch vụ vận tải hàng hóa bằng đường thủy theo hình thức: cho thuê xà lan, cho thuê tàu biển, cho thuê phà đi biển, cho thuê xà lan há mòm chở xe tải, xe đầu kéo container từ đất liền đi Đảo Phú Quốc, Đảo Hòn Thơm, Đảo Nam Du, Đảo Thổ Châu, Đảo Hòn Trẻ, Đảo Hòn Sơn.</p></div><h2 id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; li