INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (342,2,'Có nên đóng gói khi vận chuyển hàng hóa','Một số mặt hàng nhất định không được tự đóng gói khi vận chuyển Khâu đóng gói khi vận chuyển hàng hóa vô cùng quan trọng và góp phần đảm bảo sự an toàn...','https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-47-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Một số mặt hàng nhất định không được tự đóng gói khi vận chuyển</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Khâu đóng gói khi vận chuyển hàng hóa vô cùng quan trọng và góp phần đảm bảo sự an toàn, nguyên vẹn trong suốt quá trình giao nhận. Vì vậy, chúng ta không nên tự đóng gói hàng hóa tại nhà, nhất là một số mặt hàng dưới đây. Bởi điều đó có thể là nguyên nhân khiến hàng hóa bị hư hỏng, móp méo hay dập nát.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Vậy cùng tìm hiểu xem đâu là loại hàng hóa không thể tự đóng gói tại nhà mà cần một đơn vị thực hiện chuyên nghiệp.</span></p><div id=\\\"attachment_3657\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3657\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-3657\\\" src=\\\