INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (410,2,'Vận chuyển hàng quá khổ, hàng cồng kềnh đi Phú Quốc bằng những phương tiện nào?','vVận chuyển hàng quá khổ, hàng cồng kềnh đi Phú Quốc bằng những phương tiện nào? Hàng hóa quá khổ, kích thước công kềnh vượt quá quy định của...','https://conruabien.vn/wp-content/uploads/2021/06/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-K%C3%ADnh-C%C6%B0%E1%BB%9Dng-L%E1%BB%B1c-HCM-%C4%91i-Casino-Ph%C3%BA-Qu%E1%BB%91c-21.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-align: start; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><a data-mil=\\\"2171\\\" href=\\\"https://conruabien.vn/tin-tuc/van-chuyen-hang-qua-kho-hang-cong-kenh-di-phu-quoc/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(0, 0, 0); text-decoration: none;\\\">Vận chuyển hàng quá khổ, hàng cồng kềnh đi Phú Quốc</a><span>&nbsp;</span>bằng những phương tiện nào?</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Hàng hóa quá khổ, kích thước công kềnh vượt quá quy định của Bộ giao thông vận tải thì vận chuyển bằng phương tiện nào từ Sài Gòn đi Phú Quốc? Thời gian vận chuyển hàng hóa có nhanh không? Vận chuyển hàng quá khổ, hàng cồng kềnh đi Phú Quốc có phức tạp không ?</strong></span></p><div id=\\\"attachment_1962\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-1962\\\" decoding=\\\"async\\\" class=\\\"wp-image-1962 size-full\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Van-chuyen-hang-gia-tri-cao-di-Phu-Quoc-10.jpg\\\" alt=\\\"(Ảnh tin tức: vận chuyển hàng quá khổ đi phú quốc, vận chuyển hàng cồng kềnh đi phú quốc)\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/06/Van-chuyen-hang-gia-tri-cao-di-Phu-Quoc-10.jpg 2400w, https://conruabien.vn/wp-conten