INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (415,2,'Vận chuyển hàng hoá đi Phú Quốc: Mặt hàng nào được coi là giá trị cao?','Vận chuyển hàng hoá đi Phú Quốc: Mặt hàng nào được coi là giá trị cao? Đời sống xã hội ngày càng được nâng cao nên nhu cầu dùng các sản phẩm giá...','https://conruabien.vn/wp-content/uploads/2021/04/du-an-hinh-anh-van-chuyen-thiet-bi-cap-treo-di-hon-thom-bang-xe-dau-keo-container-14.jpg','\"<p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0); font-family: &quot;times new roman&quot;, times, serif; font-size: 14pt;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Đời sống xã hội ngày càng được nâng cao nên nhu cầu dùng các sản phẩm giá trị cao cũng không ngừng tăng lên. Theo đó, nhu cầu vận chuyển hàng hoá giá trị cao đi Phú Quốc và ngược lại cũng phát triển và đa dạng về chủng loại hàng hoá.</strong></span></p><div id=\\\"attachment_1538\\\" class=\\\"wp-caption aligncenter\\\" style=\\\"box-sizing: border-box; clear: both; display: block; margin: 5px auto; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px