INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (441,2,'CHO THUÊ XE TẢI ĐI PHÚ QUỐC TỪ HÀ NỘI | 0945000006','Bạn đang muốn tìm đơn vị cho thuê xe tải đi Phú Quốc từ Hà Nội giá rẻ mà đảm bảo xe mới, được trang bị đầy đủ các thiết bị hiện đại… ','https://conruabien.vn/wp-content/uploads/2021/05/D%E1%BB%B1-%C3%81n-v%E1%BA%ADn-chuy%E1%BB%83n-c%C3%A1p-%C4%91i%E1%BB%87n-t%E1%BB%AB-B%E1%BA%AFc-v%C3%A0o-Nam-v%C3%A0-%C4%91i-kh%E1%BA%AFp-c%C3%A1c-t%E1%BB%89nh-mi%E1%BB%81n-t%C3%A2y-20.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Dịch vụ cho thuê xe tải đi Phú Quốc từ Hà Nội uy tín, giá tốt nhất thị trường</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Nói đến<span>&nbsp;</span><a data-mil=\\\"4612\\\" href=\\\"https://conruabien.vn/tin-tuc/dich-vu-cho-thue-xe-tai-di-phu-quoc-tu-ha-noi-0945000006/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">dịch vụ cho thuê xe tải đi Phú Quốc từ Hà Nội</a><span>&nbsp;</span>thì Con Rùa Biển đang là cái tên được nhắc đến nhiều nhất hiện nay. Cùng tìm hiểu vì sao là Con Rùa Biển mà không phải một công ty vận tải khác.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Thực tế, trong ngành<span>&nbsp;</span><span style=\\\"box-sizing: border-box; color: rgb(255, 102, 0);\\\"><a href=\\\"http://vantainoidia.vn/dich-vu/chanh-xe-van-chuyen-hang-hoa-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">vận chuyển hàng hóa đi Phú Quốc</a></span><span>&nbsp;</span>ở trong nước với cái tên Con Rùa Biển đã khá quen thuộc với khách hàng từ cá nhân đến doanh nghiệp. Bởi công ty Con Rùa Biển với hơn 15 năm kinh nghiệm hoạt động trong lĩnh vực vận tải hàng hoá và cho thuê xe tải đã thật sự tạo được chỗ đứng trong lòng khách hàng nhờ vào nhiều yếu tố quyết định.</span></p><div id=\\\"attachment_4200\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-4200\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-4200\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-3.jpg\\\" alt=\\\"Chanh xe van chuyen hang hoa di Phu Quoc 2022 05 26 3\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-3.jpg 2400w, https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-3-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-3-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-di-Phu-Quoc-2022-05-26-3-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-4200\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN nhận vận chuyển hàng hóa đi Phú Quốc; Trong ảnh là cảnh xe tải đi giao hàng hóa bồn hóa chất dùng trong nghành xây dựng tại công trình ở trên đảo Phú Quốc, tại công trình được xuống hàng bằng cách dùng xe xúc kéo cái bồn hóa chất ra sau đuôi xe tải, sau đó dùng xe nâng hạ cái bồn hóa chất xuống đất)</p></div><div id=\\\"attachment_3844\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3844\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-3844\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-52.jpg\\\" alt=\\\"Van chuyen da hoa cuong di Phu Quoc 52\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-52.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-52-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-52-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-52-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3844\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Đá Hoa Cương đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh xe tải chở đá hoa cương đi lấy hàng tận nơi cho khách ở HCM, sau đó chạy thẳng ra đảo Phú Quốc giao hàng tận chân công trình, dự án này xe tải không vào được, phải dùng xe cẩu hàng từ xe tải qua xe cẩu, sau đó xe cẩu chở đá hoa cương di chuyển vào công trình, lại cẩu hạ xuống đất vào vị trí yêu cầu của công trình, như vậy là giao hàng hoàn tất sau khi hạ hết đá hoa cương theo yêu cầu chỉ định)</p></div><div id=\\\"attachment_3843\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3843\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3843\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-51.jpg\\\" alt=\\\"Van chuyen da hoa cuong di Phu Quoc 51\\\" width=\\\"2400\\\" height=\\\"1600\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-51.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-51-768x512.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-51-1536x1024.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-51-2048x1365.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3843\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Đá Hoa Cương đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh xe cẩu đưa kiện đá từ dưới kho tại HCM lên xe tải để xếp hàng đá hóa cương chở đi Phú Quốc giao tận nơi cho khách hàng)</p></div><div id=\\\"attachment_3823\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3823\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3823\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/10/Van-chuyen-da-hoa-cuong-di-Phu-Quoc-31.jpg\\\" alt=\\\"Van chuyen da hoa cuong di Phu Quoc 31\\\" width=\\\"2400\\\" height