INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (445,2,'GỬI HÀNG HÓA TỪ BẮC NINH ĐI PHÚ QUỐC | 0945000006','Bắc Ninh cũng là một trong số tỉnh thành có nền kinh tế phát triển vượt bậc ở khu vực phía Bắc. Chính vì thế mà nhu cầu Gửi hàng hóa từ Bắc Ninh đi Phú Quốc hay từ Bắc Ninh đi các nơi vô cùng nhộn nhịp.','https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-23-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-9\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Gửi hàng hóa từ Bắc Ninh đi Phú Quốc phổ biến mặt hàng nào?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Bắc Ninh cũng là một trong số tỉnh thành có nền kinh tế phát triển vượt bậc ở khu vực phía Bắc. Chính vì thế mà nhu cầu<span>&nbsp;</span><a data-mil=\\\"4376\\\" href=\\\"https://conruabien.vn/tin-tuc/gui-hang-hoa-tu-bac-ninh-di-phu-quoc-0945000006/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Gửi hàng hóa từ Bắc Ninh đi Phú Quốc</a><span>&nbsp;</span>hay từ Bắc Ninh đi các nơi vô cùng nhộn nhịp.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Trong đó, nhu cầu Gửi hàng hóa từ Bắc Ninh đi Phú Quốc không hề ít với một số mặt hàng trọng điểm, và nhiều hình thức<span>&nbsp;</span><a href=\\\"http://vantainoidia.vn/dich-vu/chanh-xe-van-chuyen-hang-hoa-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">vận chuyển hàng hóa đi Phú Quốc</a><span>&nbsp;</span>cũng khác nhau.</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Vậy cùng tìm hiểu xem đâu là mặt hàng phổ biến được vận chuyển từ Bắc Ninh đi Phú Quốc ngay trong bài viết dưới đây.</span></p><div id=\\\"attachment_4349\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-4349\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-4349\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-50.jpg\\\" alt=\\\"Du an van chuyen hang xe dien di Phu Quoc 50\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-50.jpg 2400w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-50-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-50-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-50-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-4349\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN nhận vận chuyển hàng xe điện đi Phú Quốc; Trong ảnh là cảnh xe điện đang nằm trong container, hàng này được nhập trực tiếp từ nước ngoài về Việt Nam, sau đó rút container tại cảng để đưa đi Phú Quốc)</p></div><div id=\\\"attachment_4308\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-4308\\\" decoding=\\\"async\\\" class=\\\"size-full wp-image-4308\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-9.jpg\\\" alt=\\\"Du an van chuyen hang xe dien di Phu Quoc 9\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-9.jpg 2400w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-9-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-9-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-9-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-4308\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN nhận vận chuyển hàng xe điện đi Phú Quốc; Trong ảnh là cảnh xe tải và xe cẩu đang trong quá trình giao nhận xe điện tại Gành Dầu Phú Quốc, xe điện đi Phú Quốc được giao nhận cho dự án Grand World Phú Quốc)</p></div><div id=\\\"attachment_4250\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-4250\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-4250\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2022/05/Chanh-xe-van-chuyen-hang-hoa-tu-s