INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (447,2,'NHÀ XE 2 CHIỀU NHẬN HÀNG ĐI PHÚ QUỐC TỪ SÀI GÒN | 0945000006','Dịch vụ của nhà xe 2 chiều nhận hàng đi Phú Quốc ngày càng đa dạng đáp ứng mọi nhu cầu vận chuyển của cá nhân, doanh nghiệp','https://conruabien.vn/wp-content/uploads/2022/06/Du-an-van-chuyen-hang-xe-dien-di-Phu-Quoc-55-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Nhà xe 2 chiều nhận hàng đi Phú Quốc từ Sài Gòn cung cấp dịch vụ nào?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Dịch vụ của nhà xe 2 chiều nhận hàng đi Phú Quốc ngày càng đa dạng đáp ứng mọi nhu cầu vận chuyển của cá nhân, doanh nghiệp hay đơn vị, tổ chức… Vậy dịch phổ biến mà các<span>&nbsp;</span><a data-mil=\\\"4361\\\" href=\\\"https://conruabien.vn/tin-tuc/nha-xe-2-chieu-nhan-hang-di-phu-quoc-tu-sai-gon-0945000006/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\">Nhà xe 2 chiều nhận hàng đi Phú Quốc từ Sài Gòn</a><span>&nbsp;</span>cung cấp là gì?</strong></span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Các bạn cùng tìm hiểu ngay bài viết dưới đây để hiểu rõ các dịch vụ mà<span>&nbsp;</span><a href=\\\"http://vantainoidia.vn/dich-vu/chanh-xe-van-chuyen-hang-hoa-di-phu-quoc.html\\\" rel=\\\"nofollow noopener\\\" target=\\\"_blank\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Nhà xe 2 chiều nhận hàng đi Phú Quốc từ Sài Gòn</strong></a><span>&nbsp;</span>và có sự lựa chọn phù hợp nhất.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetic