 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-3623\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3623\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-3-scaled.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 3 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-3-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-3-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-3-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-3-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3623\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất bàn ghế tủ áo của Khách hàng đang được công nhân bốc xếp từ kho ra để ngoài đường lớn, và sau đó đưa nội thất từ dưới đất xếp lên xe tải để đi Phú Quốc, lô hàng nội thất được vận chuyển ban đêm lúc 12h khuya tại HCM, do xe tải lớn vào TP.HCM sau 22h nên chỉ có thể vận chuyển hàng ban đêm)</p></div><div id=\\\"attachment_3624\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-3624\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3624\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-4-scaled.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 4 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-4-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-4-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-4-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-4-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3624\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất bàn ghế tủ áo của Khách hàng đang được công nhân bốc xếp từ kho ra để ngoài đường lớn, và sau đó đưa nội thất từ dưới đất xếp lên xe tải để đi Phú Quốc, lô hàng nội thất được vận chuyển ban đêm lúc 12h khuya tại HCM, do xe tải lớn vào TP.HCM sau 22h nên chỉ có thể vận chuyển hàng ban đêm)</p></div><div id=\\\"attachment_3625\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3625\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3625\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-5.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 5\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-5.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-5-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-5-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-5-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3625\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất bàn ghế tủ áo chăn ga gối nệm đang được đưa lên xe tải tại Chành xe Phú Quốc hcm vào buổi chiều, để chuẩn bị xuất phát đi Phú Quốc)</p></div><h2 id=\\\"ftoc-heading-4\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Đội ngũ nhân viên bốc xếp, đóng gói chuyên nghiệp</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Vận chuyển dọn nhà đi Phú Quốc</strong><span>&nbsp;</span>thường là những vật dụng nhỏ, dễ vỡ và khó đóng gói. Nếu không cẩn thận dễ bị rơi vỡ và mất mát trong quá trinh vận chuyển. Nhưng với đội ngũ công ty Con Rùa Biển thì các bạn hoàn toàn có thể yên tâm.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Với kinh nghiệm hơn 10 năm nên họ đảm bảo hàng hóa được đóng gói, sắp xếp cẩn thận tránh bị thất lạc hay mất mát. Đóng gói hàng hóa theo đúng tiêu chuẩn nên cũng đảm bảo hạn chế tối đa rủi ro trong quá trình vận chuyển.</span></p><div id=\\\"attachment_3564\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-3564\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3564\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-13-scaled.jpg\\\" alt=\\\"Van chuyen may bom tu HA Noi di Phu Quoc ghep xe tai duong bo 13 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-13-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-13-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-13-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-13-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3564\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Nhận gửi hàng máy bơm nhỏ lẻ đi Phú Quốc, nhận chuyển hàng Máy Bơm đi Hà Nội, cho thuê xe chở máy bơm đi Đà Nẵng từ HCM tại Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN. Trong ảnh là cảnh hàng hóa thiết bị máy bơm đang được đóng kiện gỗ tại Kho của Khách hàng trước khi xe tải bên Con Rùa Biển đến để vận chuyển đi giao tận chân công trình, ngoài việc vận chuyển thiết bi và máy bơm đi Phú Quốc thì Con Rùa Biển có mở rộng thêm dịch vụ nhận đóng kiện gỗ đảm bảo hàng hóa an toàn khi vận chuyển đường dài Bắc Nam hay vận chuyển đi Phú Quốc)</p></div><div id=\\\"attachment_3565\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1930px;\\\"><img aria-describedby=\\\"caption-attachment-3565\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3565\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-14-scaled.jpg\\\" alt=\\\"Van chuyen may bom tu HA Noi di Phu Quoc ghep xe tai duong bo 14 scaled\\\" width=\\\"1920\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-14-scaled.jpg 1920w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-14-768x1024.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-14-1152x1536.jpg 1152w, https://conruabien.vn/wp-content/uploads/2021/09/Van-chuyen-may-bom-tu-HA-Noi-di-Phu-Quoc-ghep-xe-tai-duong-bo-14-1536x2048.jpg 1536w\\\" sizes=\\\"(max-width: 1920px) 100vw, 1920px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3565\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px