px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3500\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3500\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/MAY-BOM-KH-BEE-LGT-KHO-HCM-DI-PQ-6.jpg\\\" alt=\\\"MAY BOM KH BEE LGT KHO HCM DI PQ 6\\\" width=\\\"2400\\\" height=\\\"1350\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/MAY-BOM-KH-BEE-LGT-KHO-HCM-DI-PQ-6.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/MAY-BOM-KH-BEE-LGT-KHO-HCM-DI-PQ-6-768x432.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/MAY-BOM-KH-BEE-LGT-KHO-HCM-DI-PQ-6-1536x864.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/MAY-BOM-KH-BEE-LGT-KHO-HCM-DI-PQ-6-2048x1152.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3500\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Máy Bơm đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN. Nội dung công việc thực hiện là dùng xe đầu kéo container kéo container từ Cảng Cát Lái HCM về kho Con Rùa Biển HCM, rút container hàng máy bơm tại chành xe HCM, để đưa qua xe tải của Chành xe Con Rùa Biển, sau đó vận chuyển đi ghép qua đảo Phú Quốc, hình thức vận chuyển kết hợp để tiết kiệm chi phí so với phương án vận chuyển hàng máy bơm bao xe nguyên chiếc đi thẳng Phú Quốc, đi Nguyên container nguyên seal giá trung bình 30 triệu/cont, nếu ghép xe thì còn có khoãng 10 triệu. Nên phương án đi ghép kết hợp đảm bảo hàng hóa giá rẻ luôn là phương án tối ưu chi phí vận chuyển máy bơm nhất hiện này khi vận chuyển hàng máy bơm đi phú quốc bằng đường bộ xe tải kết hợp hàng hóa nhỏ lẻ khác. Trong ảnh là cảnh xe đầu kéo đưa hàng máy bơm về kho, chuẩn bị dùng xe nâng rút container)</p></div><div id=\\\"attachment_3470\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 1692px;\\\"><img aria-describedby=\\\"caption-attachment-3470\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3470\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-Thang-May-di-Phu-Quoc-cua-SunHome-An-thoi-6-scaled.jpg\\\" alt=\\\"Du an Van chuyen Thang May di Phu Quoc cua SunHome An thoi 6 scaled\\\" width=\\\"1682\\\" height=\\\"2560\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-Thang-May-di-Phu-Quoc-cua-SunHome-An-thoi-6-scaled.jpg 1682w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-Thang-May-di-Phu-Quoc-cua-SunHome-An-thoi-6-768x1169.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-Thang-May-di-Phu-Quoc-cua-SunHome-An-thoi-6-1009x1536.jpg 1009w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-Thang-May-di-Phu-Quoc-cua-SunHome-An-thoi-6-1346x2048.jpg 1346w\\\" sizes=\\\"(max-width: 1682px) 100vw, 1682px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3470\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Thang Máy Băng Tải đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN ở khu Công trình SunHome An Thới Phú Quốc Kiên Giang. Hình thức vận chuyển là dùng Xe đầu kéo container sẽ vận chuyển Container từ Cảng Cát Lái HCM đi Phú Quốc chở hàng Thang Máy Băng Tải – vật tư thiết bị công trình, giao hàng tại đây và kèm theo dịch vụ mở rộng Cho thuê xe cẩu 20 tấn nhận rút hàng container và di chuyển hàng vào vị trí lắp đặt thang máy tại Công trình bằng xe nâng máy dầu. Trong ảnh là hình ảnh trang thiết bị vật tư thang máy đang được xe cẩu rút ra ngoài, hạ xuống đất, sau đó xe nâng sẽ nâng hàng đưa vào trong tòa nhà tại công trình)</p></div><h2 id=\\\"ftoc-heading-3\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đơn vị nào vận chuyển xe đầu kéo đi Phú Quốc với giá cước tốt nhất?</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Con Rùa Biển chính là cái tên đang được mọi khách hàng dù là cá nhân hay doanh nghiệp lựa chọn nhiều nhất hiện nay. Với hơn 15 năm kinh nghiệm hoạt động trong lĩnh vực vận tải hàng hoá Bắc Nam, các tỉnh miền Trung, miền Tây hay bất cứ địa điểm nào trên mọi miền tổ quốc.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Riêng về dịch vụ vận chuyển xe đầu kéo đi Phú Quốc các bạn hoàn toàn có thể yên tâm về chất lượng, thời gian và giá cước. Với đội ngũ nhân viên chuyên nghiệp và giàu kinh nghiệm sẽ vận chuyển xe đầu kéo đến tận nơi nhận hàng trong thời gian nhanh nhất. Mà hạn chế tối đa rủi ro hư hỏng hay gặp trục trắc trên đường vận chuyển.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Tuỳ theo yêu cầu của khách hàng mà đội ngũ nhân viên Con Rùa Biển sẽ đưa ra giải pháp vận chuyển xe đầu kéo đi Phú Quốc tốt nhất. Cam kết xe đầu kéo còn nguyên chất lượng, không hư hỏng và chạy tốt ngay sau khi nhận hàng.</span></p><div id=\\\"attachment_3456\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3456\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3456\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-6.jpg\\\" alt=\\\"Du an Van chuyen thang may di Phu Quoc cua Mariot 6\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-6.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-6-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-6-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-6-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3456\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Thang Máy Băng Tải đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN ở khu Công trình JW Marriott Phu Quoc Emerald Bay. Hình thức vận chuyển là dùng Xe đầu kéo container sẽ vận chuyển Container từ Cảng Cát Lái HCM đi Phú Quốc chở hàng Thang Máy Băng Tải – vật tư thiết bị công trình, giao hàng tại đây và kèm theo dịch vụ mở rộng Cho thuê xe cẩu 20 tấn nhận rút hàng container và di chuyển hàng vào vị trí lắp đặt thang máy tại Công trình. Trong ảnh là cảnh xe cẩu 20 tấn đang rút hàng từ trong container ra ngoài và hạ hàng thiết bị thang máy xuống bãi tập kết, sau đó kiểm tra lại trước khi di chuyển vào vị trí lắp đặt)</p></div><div id=\\\"attachment_3452\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3452\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3452\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-2.jpg\\\" alt=\\\"Du an Van chuyen thang may di Phu Quoc cua Mariot 2\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-2.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-2-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-2-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-thang-may-di-Phu-Quoc-cua-Mariot-2-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3452\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Thang Máy Băng Tải đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN ở khu Công trình JW Marriott Phu Quoc Emerald Bay. Hình thức vận chuyển là dùng Xe đầu kéo container sẽ vận chuyển Container từ Cảng Cát Lái HCM đi Phú Quốc chở hàng Thang Máy Băng Tải – vật tư thiết bị công trình, giao hàng tại đây và kèm theo dịch vụ mở rộng Cho thuê xe cẩu 20 tấn nhận rút hàng container và di chuyển hàng vào vị trí lắp đặt thang máy tại Công trình. Trong ảnh là cảnh xe cẩu 20 tấn đang rút hàng từ trong container ra ngoài và sang xe cẩu khác để di chuyển vào công trình để hạ cho nhanh và thuận lợi)</p></div><div id=\\\"attachment_3422\\\" class=\\\"wp-caption alignnone\\\" style=\\\"box-sizing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1p