INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (466,2,'CHUYỂN PHÁT NHANH SÀI GÒN PHÚ QUỐC | 0945000006','Bạn đang có nhu cầu sử dụng dịch vụ chuyển phát nhanh Sài Gòn Phú Quốc. Vậy thì việc bạn cần làm không chỉ có tìm đơn vị chuyển phát nhanh uy tín, giá tốt','https://conruabien.vn/wp-content/uploads/2021/06/D%E1%BB%B1-%C3%A1n-v%E1%BA%ADn-chuy%E1%BB%83n-K%C3%ADnh-C%C6%B0%E1%BB%9Dng-L%E1%BB%B1c-HCM-%C4%91i-Casino-Ph%C3%BA-Qu%E1%BB%91c-20.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">3 lưu ý về việc chuẩn bị hàng hóa trước khi chuyển phát nhanh Sài Gòn Phú Quốc</span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"b