izing: border-box; margin: 5px 20px 20px 0px; background: rgb(247, 247, 247); border: 1px solid rgb(230, 230, 230); max-width: 100%; padding: 10px; text-align: center; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; width: 2410px;\\\"><img aria-describedby=\\\"caption-attachment-3621\\\" decoding=\\\"async\\\" loading=\\\"lazy\\\" class=\\\"size-full wp-image-3621\\\" src=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-1.jpg\\\" alt=\\\"Du an Van chuyen noi that di Phu Quoc 1\\\" width=\\\"2400\\\" height=\\\"1800\\\" srcset=\\\"https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-1.jpg 2400w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-1-768x576.jpg 768w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-1-1536x1152.jpg 1536w, https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-1-2048x1536.jpg 2048w\\\" sizes=\\\"(max-width: 2400px) 100vw, 2400px\\\" style=\\\"box-sizing: border-box; height: auto; max-width: 100%; border: 0px none; vertical-align: middle; margin: 0px; padding: 0px; width: auto;\\\"><p id=\\\"caption-attachment-3621\\\" class=\\\"wp-caption-text\\\" style=\\\"box-sizing: border-box; margin: 0px; font-size: 11px; line-height: 17px; padding: 5px;\\\">(Hình ảnh Dự án vận chuyển Nội Thất đi Phú Quốc – Chành xe Hà Nội Sài Gòn Phú Quốc – CON RÙA BIỂN; Trong ảnh là cảnh nội thất bàn ghế tủ áo của Khách hàng đưa ra bãi xe tại HCM, sau đó bốc xếp dùng xe nâng đưa hàng nội thất lên xe tải vào buổi chiều để xuất phát đi Phú Quốc, sẽ kịp giao hàng vào sáng ngày hôm sau tại Phú Quốc một cách nhanh nhất có thể)</p></div><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Đội ngũ nhân viên của công ty Con Rùa Biển đều có kinh nghiệm đảm bảo hàng hóa đóng gói đúng tiêu chuẩn và việc bốc dỡ cũng trở nên nhanh chóng. Bảng cước phí<span>&nbsp;</span><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">xe tải gửi hàng đi Phú Quốc</strong><span>&nbsp;</span>cũng được đánh giá là cạnh tranh nhất thị trường.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\">Các bạn đã hiểu lý do vì sao Con Rùa Biển lại được mọi người tin tưởng lựa chọn nhiều như vậy khi có nhu cầu vận chuyển hàng hóa đúng không nào. Một địa chỉ xứng đáng để bạn gửi trọn niềm tin.</span></p><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: right;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">(Nguồn:<span>&nbsp;</span></em></strong><a href=\\\"https://www.conruabien.vn/\\\" style=\\\"box-sizing: border-box; background-color: transparent; color: rgb(255, 102, 0); text-decoration: none;\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">www.conruabien.vn</em></strong></a><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\"><span>&nbsp;</span>– Chành xe Phú Quốc –<span>&nbsp;</span></em></strong><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">0945000006</em></strong><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\"><em style=\\\"box-sizing: border-box;\\\">)</em></strong></p>\"','2024-06-18 18:55:18','/tin-tuc/don-vi-cung-cap-dich-vu-xe-tai-gui-hang-di-phu-quoc-nao-uy-tin-va-gia-re',NULL,0,5,NULL,NULL,NULL);
INSERT INTO post (`id`,`topic_id`,`name`,`description`,`title_image`,`content`,`date_post`,`url_name`,`author`,`is_hidden`,`category_id`,`icon`,`keyword`,`table_id`) VALUES (507,2,'TOP 3 DỊCH VỤ CHÍNH CỦA XE TẢI CHUYỂN HÀNG ĐI PHÚ QUỐC BẠN CẦN BIẾT','Bạn đang có nhu cầu sử dụng dịch vụ xe tải chuyển hàng đi Phú Quốc. Nhưng chưa hiểu rõ về các dịch vụ vận chuyển xe tải đi Phú Quốc để có sự lựa chọn phù hợp.','https://conruabien.vn/wp-content/uploads/2021/09/Du-an-Van-chuyen-noi-that-di-Phu-Quoc-38-2048x1536.jpg','\"<h2 id=\\\"ftoc-heading-1\\\" class=\\\"ftwp-heading\\\" style=\\\"box-sizing: border-box; font-family: utm_helveins; font-weight: normal !important; line-height: 1.4; color: rgb(10, 10, 10); margin-top: 20px; margin-bottom: 10px; font-size: 30px; text-transform: none; letter-spacing: normal; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; text-indent: 0px; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span style=\\\"box-sizing: border-box; color: rgb(0, 0, 0);\\\"><strong style=\\\"box-sizing: border-box; font-weight: bold;\\\">Top 3 dịch vụ chính của xe tải chuyển hàng đi Phú Quốc bạn cần biết</strong></span></h2><p style=\\\"box-sizing: border-box; margin: 0px 0px 10px; color: rgb(200, 50, 43); font-family: &quot;\\\\&quot;roboto\\\\&quot;, helvetica, arial&quot;, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-align: justify;\\\"><span styl